export const drillLevel1 = [
  { id: 1, level: 1, category: '利回り基礎', question: '表面利回りの計算式として正しいものはどれですか？', choices: ['年間家賃収入 ÷ 物件価格 × 100', '月額家賃 ÷ 物件価格 × 100', '年間家賃収入 ÷ 管理費 × 100', '物件価格 ÷ 年間家賃収入 × 100'], correct: 0, explanation: '表面利回り（%）= 年間家賃収入 ÷ 物件価格 × 100。諸経費を含まないシンプルな計算式で、物件比較の第一歩として使われます。' },
  { id: 2, level: 1, category: '利回り基礎', question: '物件価格2,000万円・月額家賃8万円の表面利回りはいくらですか？', choices: ['5.2%', '4.8%', '6.0%', '3.6%'], correct: 1, explanation: '年間家賃 = 8万円 × 12 = 96万円。96万円 ÷ 2,000万円 × 100 = 4.8%。まず年間家賃に換算する習慣をつけましょう。' },
  { id: 3, level: 1, category: '利回り基礎', question: '表面利回りと実質利回りの主な違いはどれですか？', choices: ['表面利回りは税金を含めて計算する', '実質利回りは月額家賃で計算する', '実質利回りは経費を差し引いて計算する', '両者に違いはなく同じ意味で使われる'], correct: 2, explanation: '実質利回りは管理費・修繕費・税金などの諸経費を差し引いた純収益で計算します。表面利回りより低くなりますが、実態に近い数字です。' },
  { id: 4, level: 1, category: '利回り基礎', question: '一般的に不動産投資で「高利回り」と呼ばれる目安はどれですか？', choices: ['2%以上', '0.5%以上', '15%以上', '8%以上'], correct: 3, explanation: '目安として8%以上が「高利回り」とされることが多いです。ただし高利回り物件はリスク（築古・地方・空室率など）も高い傾向があります。' },
  { id: 5, level: 1, category: '利回り基礎', question: '利回りが高い物件にはどんなリスクが伴いやすいですか？', choices: ['築年数が古く修繕費がかかりやすい', '家賃が低すぎて管理が簡単すぎる', '需要が高すぎて入居者が選べない', '金利優遇が受けやすく融資が通りやすい'], correct: 0, explanation: '高利回りの裏には理由があります。築古・地方・駅遠・事故物件など。利回りだけで判断せず、なぜ高いのかを必ず調べる習慣が大切です。' },
  { id: 6, level: 1, category: '利回り基礎', question: '物件価格が上がると利回りはどう変化しますか？', choices: ['家賃が同じなら利回りは上がる', '家賃が同じなら利回りは下がる', '物件価格と利回りは無関係', '物件価格が上がると家賃も必ず上がる'], correct: 1, explanation: '利回り = 家賃 ÷ 物件価格。分母が大きくなれば利回りは低下します。都心の高額物件が低利回りになりやすいのはこのためです。' },
  { id: 7, level: 1, category: '利回り基礎', question: '「グロス利回り」と同じ意味の言葉はどれですか？', choices: ['実質利回り', 'ネット利回り', '表面利回り', 'キャップレート'], correct: 2, explanation: 'グロス（Gross）は「総体の・税引き前の」という意味。グロス利回り＝表面利回りで、経費を差し引く前の数字です。ネット＝実質利回りと対比して覚えましょう。' },
  { id: 8, level: 1, category: '利回り基礎', question: '年間家賃収入120万円・物件価格1,500万円の表面利回りはいくらですか？', choices: ['6.5%', '10.0%', '7.2%', '8.0%'], correct: 3, explanation: '120万円 ÷ 1,500万円 × 100 = 8.0%。この計算はパッと暗算できるようになると物件比較がスムーズになります。' },
  { id: 9, level: 1, category: '利回り基礎', question: '表面利回り6%・物件価格1,000万円の物件の年間家賃収入はいくらですか？', choices: ['60万円', '600万円', '6万円', '160万円'], correct: 0, explanation: '年間家賃 = 物件価格 × 表面利回り = 1,000万円 × 6% = 60万円。逆算できると「この家賃なら何%か」も瞬時に判断できます。' },
  { id: 10, level: 1, category: '利回り基礎', question: '利回りを比較する際、最も重要な前提条件はどれですか？', choices: ['物件価格が同じ物件で比べる', '同じ計算方式（表面か実質か）で比べる', '同じ都市の物件で比べる', '建物構造が同じ物件で比べる'], correct: 1, explanation: '表面と実質を混在させると正確な比較ができません。「表面6% vs 実質6%」は全く別物。比較する際は必ず同じ基準を使いましょう。' },
  { id: 11, level: 1, category: '空室・管理', question: '空室率とはどのような指標ですか？', choices: ['入居者の退去回数の割合', '家賃滞納率のこと', '全戸数に対する空室の割合', '物件の稼働日数の割合'], correct: 2, explanation: '空室率 = 空室数 ÷ 総戸数 × 100。この数字が高いほど収益が落ちます。エリアの平均空室率を調べることが投資判断の基本です。' },
  { id: 12, level: 1, category: '空室・管理', question: '空室リスクを下げるために最も効果的な要素はどれですか？', choices: ['建物の外壁をきれいに塗装する', '家賃を相場より高めに設定する', '管理会社を頻繁に変更する', '駅近・生活利便性の高い立地'], correct: 3, explanation: '立地は変えられない最重要要素。「駅徒歩10分以内」「スーパー・病院近く」など生活利便性が高いほど入居需要が安定します。' },
  { id: 13, level: 1, category: '空室・管理', question: '管理会社に支払う管理手数料の一般的な相場はどれですか？', choices: ['家賃の5〜10%程度', '家賃の30〜40%程度', '月額固定で1万円程度', '年間家賃の1%程度'], correct: 0, explanation: '一般的には家賃収入の5〜10%が管理手数料の目安。賃貸管理（入居者対応・集金・報告）が含まれます。実質利回り計算に必ず入れましょう。' },
  { id: 14, level: 1, category: '空室・管理', question: '「サブリース契約」とはどのような仕組みですか？', choices: ['入居者が直接オーナーに家賃を払う通常の契約', '管理会社が物件を借り上げて家賃を保証する契約', '複数オーナーで1棟を共同購入する契約', '銀行が不動産を担保として管理する契約'], correct: 1, explanation: 'サブリースは管理会社がオーナーから物件を借り上げ、入居者に転貸する仕組み。家賃保証がある一方、保証賃料は相場より低く・減額交渉リスクもあります。' },
  { id: 15, level: 1, category: '空室・管理', question: '入居者が退去した後、次の入居者が決まるまでの平均的な空室期間はどのくらいですか？', choices: ['1週間以内', '6ヶ月〜1年', '1〜3ヶ月程度', '2〜3年'], correct: 2, explanation: '立地や物件条件によりますが、平均1〜3ヶ月が目安。この空室期間の収入ゼロを年間収益に織り込んで計算することが重要です。' },
  { id: 16, level: 1, category: '空室・管理', question: '空室対策として家賃を下げる以外に有効な方法はどれですか？', choices: ['管理会社との契約を解除する', '物件の固定資産税を下げる申請をする', 'ローンの返済額を増やす', 'フリーレント（入居初月の家賃無料）の提供'], correct: 3, explanation: 'フリーレントは入居者の初期費用負担を軽減し、入居決定率を上げる有効な空室対策。家賃を下げるより長期的なダメージが少ない場合があります。' },
  { id: 17, level: 1, category: '空室・管理', question: '自主管理（管理会社を使わない）のデメリットとして最も大きいものはどれですか？', choices: ['クレーム・修繕対応に自分の時間が取られる', '管理手数料がかかる', '入居者と直接交渉できない', '確定申告が複雑になる'], correct: 0, explanation: '自主管理は手数料ゼロですが、深夜のトラブル対応・滞納交渉・退去清算など時間と精神的負担が大きい。初心者は管理会社委託から始めるのが無難です。' },
  { id: 18, level: 1, category: '空室・管理', question: '「原状回復」とはどのような意味ですか？', choices: ['建物を新築時の状態に戻すこと', '退去時に入居前の状態に戻すこと', '家賃を元の金額に戻すこと', 'ローン残高を当初の金額に戻すこと'], correct: 1, explanation: '原状回復とは入居者が退去する際、通常の使用による消耗を除き、故意・過失による損傷を入居前の状態に戻すこと。敷金精算のトラブルになりやすいポイントです。' },
  { id: 19, level: 1, category: '修繕', question: '築年数が経過した物件で最初に大きな修繕費がかかりやすい箇所はどれですか？', choices: ['玄関ドアの交換', '表札の取り替え', '屋根・外壁の防水・塗装', '郵便ポストの修理'], correct: 2, explanation: '屋根・外壁の防水劣化は建物全体に影響します。一般的に10〜15年周期での塗装・防水工事が必要で、1回あたり数百万円規模になることも。購入前に築年数と修繕履歴を必ず確認しましょう。' },
  { id: 20, level: 1, category: '修繕', question: 'マンション投資で毎月積み立てる「修繕積立金」の目的は何ですか？', choices: ['毎月の管理会社への報酬のため', '固定資産税の支払いのため', 'ローンの繰り上げ返済のため', '将来の大規模修繕工事に備えるため'], correct: 3, explanation: '修繕積立金はエレベーター・外壁・共用部など大規模修繕の資金を毎月少額ずつ積み立てるもの。積立額が少ない管理組合は将来の一時負担金リスクがあります。' },
  { id: 21, level: 1, category: '修繕', question: 'キャッシュフロー計算で修繕費の目安として使われる考え方はどれですか？', choices: ['家賃収入の一定割合（5〜10%）を毎月積み立てる', '修繕が必要になったときだけ費用を計上する', '修繕費はオーナー負担ではなく入居者負担', '10年に一度だけ大きな費用を計上する'], correct: 0, explanation: '実務では家賃収入の5〜10%を修繕費として毎月計上しておくのが一般的。突発的な修繕でキャッシュフローがマイナスにならないよう備えることが大切です。' },
  { id: 22, level: 1, category: '修繕', question: '入居者退去後の「リフォーム費用」は主に誰が負担しますか？', choices: ['全額入居者負担が原則', 'オーナーが負担するケースが多い', '管理会社が全額負担する', '国の補助金で賄われる'], correct: 1, explanation: '通常の使用による経年劣化（壁紙・畳など）はオーナー負担が基本。ただし入居者の故意・過失による損傷は入居者負担。国土交通省のガイドラインを把握しておきましょう。' },
  { id: 23, level: 1, category: '修繕', question: '築20年以上の木造アパートを購入する際、特に注意すべき点はどれですか？', choices: ['壁紙の色合いと入居者の好み', '表札プレートの素材', '給排水管・電気設備の劣化状況', '駐輪場の台数'], correct: 2, explanation: '給排水管や電気設備は目に見えにくい劣化が進みやすく、修繕費が高額になりがち。購入前のインスペクション（建物調査）で確認することがリスク回避の鍵です。' },
  { id: 24, level: 1, category: '修繕', question: '「インスペクション」とは不動産投資でどんな意味ですか？', choices: ['入居者の身元確認調査', '固定資産税の評価額調査', '周辺家賃相場の市場調査', '専門家による建物の劣化・欠陥調査'], correct: 3, explanation: 'インスペクションは建築士などの専門家が建物の状態を調査すること。中古物件購入前に行うことで、隠れた修繕リスクを事前に把握できます。費用は数万円〜十数万円程度。' },
  { id: 25, level: 1, category: '修繕', question: '「大規模修繕」が必要になるマンションの目安は築何年ごろですか？', choices: ['築12〜15年ごとが一般的な目安', '築3〜5年ごとに行う', '築50年になったら一度だけ行う', '入居者が要望したときだけ行う'], correct: 0, explanation: '一般的に12〜15年周期で外壁塗装・防水・鉄部塗装などの大規模修繕が行われます。費用は戸あたり数十万円規模。修繕計画と積立金残高は必ず確認を。' },
  { id: 26, level: 1, category: '区分/一棟', question: '「区分マンション投資」とはどのような投資ですか？', choices: ['マンション1棟を丸ごと購入する投資', 'マンションの1室（1戸）を購入して貸す投資', '土地だけを購入する投資', 'REITを購入する投資'], correct: 1, explanation: '区分マンションは1室単位での購入。初期投資額が少なく始めやすいのが特徴。ただし1室空室＝収入ゼロになるリスクがあります。' },
  { id: 27, level: 1, category: '区分/一棟', question: '一棟アパート投資の最大のメリットはどれですか？', choices: ['1室だけ購入するため管理が簡単', '修繕費が区分より必ずかからない', '複数戸あるため空室リスクが分散される', '固定資産税が区分よりかからない'], correct: 2, explanation: '一棟所有は複数戸を持つため、1〜2室空いても他の部屋の家賃収入で補えます。スケールメリットがある一方、初期投資額が大きくなります。' },
  { id: 28, level: 1, category: '区分/一棟', question: '区分マンション投資で「管理組合」が重要な理由はどれですか？', choices: ['入居者を選定する機関だから', '家賃を決定する機関だから', 'ローン審査を行う機関だから', '共用部の管理・修繕方針を決める組織だから'], correct: 3, explanation: '管理組合はマンション所有者全員で構成され、共用部の管理・修繕積立・規約変更などを決定します。管理組合の健全性が物件価値と収益に直結します。' },
  { id: 29, level: 1, category: '区分/一棟', question: '「一棟もの」投資と「区分」投資、初心者が始めやすいのはどちらですか？', choices: ['区分マンション（初期費用が少ない）', '一棟アパート（戸数が多い）', 'どちらも初期費用は同じ', '初心者は不動産投資をすべきでない'], correct: 0, explanation: '区分マンションは数百万〜数千万円からスタートでき、自己資金が少ない初心者に向いています。一棟は数千万〜数億円規模が多く、経験・資金力が求められます。' },
  { id: 30, level: 1, category: '区分/一棟', question: '「戸建て投資」の特徴として正しいものはどれですか？', choices: ['修繕費が一切かからない', '管理組合がなく自分で管理できる', '空室リスクがゼロ', '利回りは必ず低い'], correct: 1, explanation: '戸建ては管理組合がないため意思決定が自由。ただし外壁・屋根などの修繕はすべてオーナー負担。一方で築古戸建てなら安く買って高利回りを狙えるケースもあります。' },
  { id: 31, level: 1, category: '区分/一棟', question: '区分マンションで発生する「修繕積立金」と「管理費」はどのように扱われますか？', choices: ['購入時に一括で支払うもの', 'オーナーではなく入居者が支払うもの', '毎月の支出として実質利回り計算に含める', '10年に一度だけ発生するコスト'], correct: 2, explanation: '修繕積立金・管理費はオーナーが毎月支払う固定コスト。例えば合計3万円/月なら年間36万円が確実に出ていきます。利回り計算に必ず織り込みましょう。' },
  { id: 32, level: 1, category: '区分/一棟', question: '一棟アパートを購入する際、「利回り」以外に重視すべき指標はどれですか？', choices: ['建物の外壁の色', '前オーナーの年齢', '最寄り駅の名前の長さ', '土地の持分・積算価格'], correct: 3, explanation: '積算価格（土地+建物の評価額）は融資審査に影響します。利回りが高くても積算価格が低いと融資が厳しくなる場合があります。土地の価値は特に重要です。' },
  { id: 33, level: 1, category: '区分/一棟', question: '「1棟マンション」と「1棟アパート」の主な違いはどれですか？', choices: ['構造（RC造 vs 木造・軽量鉄骨）が多い', '戸数の多さ', '立地エリア', '家賃の高さ'], correct: 0, explanation: '一般的にマンションはRC（鉄筋コンクリート）造・中高層、アパートは木造・軽量鉄骨・低層が多い。RC造は耐用年数が長く融資を受けやすい一方、価格が高い傾向があります。' },
  { id: 34, level: 1, category: 'ローン基礎', question: '不動産投資ローンと住宅ローンの最も大きな違いはどれですか？', choices: ['返済期間が住宅ローンより必ず短い', '金利水準が高く、審査基準が収益性重視', '自己資金ゼロでも必ず通る', '金利は住宅ローンより必ず低い'], correct: 1, explanation: '投資用ローンは住宅ローン（0.3〜1%台）より金利が高く（1〜4%台）、審査では物件の収益性と投資家の資産背景が重視されます。居住用と混在させると規約違反になることも。' },
  { id: 35, level: 1, category: 'ローン基礎', question: '「融資LTV（Loan to Value）」とはどのような指標ですか？', choices: ['家賃収入に対する返済額の割合', '年収に対する借入総額の割合', '物件価格に対するローン残高の割合', '固定資産税に対する管理費の割合'], correct: 2, explanation: 'LTV = ローン残高 ÷ 物件価格 × 100。LTVが低いほど自己資本比率が高く安全。80%LTVなら物件価格の20%を自己資金で入れているイメージです。' },
  { id: 36, level: 1, category: 'ローン基礎', question: 'ローンの「元利均等返済」とはどのような返済方法ですか？', choices: ['毎月の元金返済額が一定', '最初の5年間だけ利息を払う', '返済額が毎年増加していく', '毎月の返済額（元金+利息）が一定'], correct: 3, explanation: '元利均等は毎月の返済額が一定で家計管理しやすい方式。返済初期は利息の割合が高く元金がなかなか減らないのが特徴。投資ローンでは最も一般的です。' },
  { id: 37, level: 1, category: 'ローン基礎', question: '返済期間を長くすることの主なメリットとデメリットはどれですか？', choices: ['月々の返済額が減るが、総返済利息が増える', '月々の返済額が増えるが、総利息が減る', '返済期間は収支に影響しない', '期間を長くすると金利が下がる'], correct: 0, explanation: '返済期間を延ばすと月々の負担は軽くなりキャッシュフローが改善しますが、長期間利息を払い続けるため総返済額は増えます。キャッシュフロー重視か総コスト重視かで判断します。' },
  { id: 38, level: 1, category: 'ローン基礎', question: '不動産投資ローンの審査で銀行が最も重視する項目はどれですか？', choices: ['投資家の趣味や生活スタイル', '年収・勤務先・保有資産・物件の収益性', '物件の外観デザイン', '入居者の職業'], correct: 1, explanation: '銀行は「返済能力」と「物件の担保価値・収益性」を重視します。年収が高く安定した勤め先で、頭金をしっかり入れることで審査通過率が上がります。' },
  { id: 39, level: 1, category: 'ローン基礎', question: '「デッドクロス」とはどのような状態ですか？', choices: ['空室率が50%を超えた状態', '家賃収入がローン返済額を下回った状態', '元金返済額が減価償却費を上回る状態', '物件価格がローン残高を下回った状態'], correct: 2, explanation: 'デッドクロスは税務上の経費（減価償却費）より実際のキャッシュアウト（元金返済）が多くなる状態。会計上は黒字でも手元資金が不足し、税負担が増える危険なポイントです。' },
  { id: 40, level: 1, category: 'ローン基礎', question: '「金利1%上昇」が月々の返済額に与える影響として正しいものはどれですか？', choices: ['借入額に関わらず影響は同じ', '返済期間が短いほど影響が大きい', '変動金利でも影響はほぼゼロ', '借入額が多いほど影響が大きい'], correct: 3, explanation: '金利1%上昇の影響は借入額に比例します。例えば2,000万円借入なら月々約1.7万円増加（35年）。複数物件でレバレッジをかけると金利上昇リスクが積み重なります。' },
  { id: 41, level: 1, category: 'ローン基礎', question: '不動産投資で「頭金」を多く入れるメリットはどれですか？', choices: ['月々の返済額が減り、金利負担も少なくなる', '頭金は多いほどリスクが高くなる', '頭金を入れると利回りが下がる', '頭金の額は審査に影響しない'], correct: 0, explanation: '頭金を多く入れることで借入額・月返済額・総利息が減り、キャッシュフローが安定します。また銀行からの信頼度が上がり、金利優遇を受けやすくなることもあります。' },
  { id: 42, level: 1, category: 'ローン基礎', question: '「団体信用生命保険（団信）」とは投資ローンにおいてどんな役割を持ちますか？', choices: ['空室時に家賃収入を保証してくれる', '借入者が死亡・高度障害時にローンが完済される', '物件が火災にあったときの修繕費を補償する', '金利上昇時に差額を補填してくれる'], correct: 1, explanation: '団信は生命保険の一種。借入者が死亡・高度障害になった際にローン残高が保険金で完済されます。遺族や相続人に「ローンなし物件」が残るため、生命保険代わりになると言われます。' },
  { id: 43, level: 1, category: '表面/実質利回り', question: '実質利回り（ネット利回り）の計算に含める経費として正しいものはどれですか？', choices: ['元金返済額・利息', '入居者の生活費', '管理費・修繕費・固定資産税・保険料', '近隣物件の家賃'], correct: 2, explanation: '実質利回り = (年間家賃 − 諸経費) ÷ 物件価格 × 100。諸経費には管理費・修繕積立金・固定資産税・火災保険料などが含まれます。ローン返済額は含みません。' },
  { id: 44, level: 1, category: '表面/実質利回り', question: '表面利回り8%の物件の実質利回りとして現実的な数字はどれですか？', choices: ['8%のまま変わらない', '10〜12%程度', '1〜2%程度', '5〜6%程度'], correct: 3, explanation: '実質利回りは諸経費分だけ表面より低くなります。一般的に表面利回りから2〜3%程度下がると言われ、表面8%なら実質5〜6%が現実的な目安です。' },
  { id: 45, level: 1, category: '表面/実質利回り', question: '物件情報に記載されている利回りは一般的に何利回りですか？', choices: ['表面利回り（グロス）', '実質利回り（ネット）', 'キャッシュオンキャッシュリターン', '税引き後利回り'], correct: 0, explanation: '不動産ポータルサイトや物件資料に掲載されているのはほぼ表面利回りです。実際の手残りを確認するには自分で実質利回りを計算する必要があります。' },
  { id: 46, level: 1, category: '表面/実質利回り', question: '「空室率5%」を加味した実質的な年間家賃収入はどのように計算しますか？', choices: ['満室家賃収入 × 1.05', '満室家賃収入 × 0.95', '満室家賃収入 ÷ 0.95', '満室家賃収入 − 5万円'], correct: 1, explanation: '空室率5%を考慮すると実際の収入は満室時の95%。年間120万円の物件なら114万円で計算します。空室リスクを織り込んだ保守的な計算が投資判断の基本です。' },
  { id: 47, level: 1, category: '表面/実質利回り', question: '「購入諸費用」を含めた利回り計算で使われる指標はどれですか？', choices: ['表面利回り', '管理利回り', '総投資利回り（物件価格+諸費用で割る）', '法定利回り'], correct: 2, explanation: '物件価格だけでなく仲介手数料・登記費用・ローン手数料などの諸費用（物件価格の7〜10%程度）を加えた「総投資額」で利回りを計算すると、より正確な投資判断ができます。' },
  { id: 48, level: 1, category: '表面/実質利回り', question: '固定資産税の目安として年間どのくらいを見込めばいいですか？', choices: ['物件価格の10%程度', '家賃収入の30%程度', '月額家賃の3倍程度', '物件価格の0.3〜0.5%程度'], correct: 3, explanation: '固定資産税は固定資産評価額の1.4%が基本税率。おおよそ物件価格の0.3〜0.5%を年間で見込むと計算しやすいです。都市計画税が加わる場合もあります。' },
  { id: 49, level: 1, category: '表面/実質利回り', question: '実質利回りを計算する目的として最も適切なものはどれですか？', choices: ['実際の手残り収益を把握するため', '物件の外観評価のため', '入居者の属性確認のため', '銀行への提出書類作成のため'], correct: 0, explanation: '実質利回りは「実際にどれだけ儲かるか」を把握するための指標。表面利回りだけで判断すると諸経費を見落とし、蓋を開けると赤字というケースも。投資前に必ず計算しましょう。' },
  { id: 50, level: 1, category: '表面/実質利回り', question: '同じ物件でも「実質利回りが高い投資家」と「低い投資家」が生まれる理由はどれですか？', choices: ['運が良いかどうかの差', '管理費・修繕費の管理コスト差や購入価格交渉の差', '物件の立地の差のみ', '入居者の職業の差'], correct: 1, explanation: '同じ物件でも購入価格の交渉・管理会社の選定・修繕コストの最適化・リフォームのDIYなどで実質利回りは変わります。投資家の実力が如実に出るポイントです。' },
];

export const drillExtreme = [
  { id: 'ex1', level: 'extreme', category: 'IRR・投資分析', question: '物件価格5,000万円・年間純収益250万円・10年後売却価格4,200万円と想定した場合、この投資のIRR（内部収益率）として最も近い値はどれですか？（初期投資は全額自己資金と仮定）', choices: ['約6.2%', '約8.5%', '約3.8%', '約11.0%'], correct: 2, explanation: 'IRRはNPV=0となる割引率。年間CF250万円×10年＋売却4,200万円を現在価値に割り引くと、概算で約3.8%になります。表面利回り5%より低くなる理由は売却時の価値減少（5,000万→4,200万の800万円損失）を10年間で吸収するためです。IRR計算はExcelのXIRR関数で正確に算出します。' },
  { id: 'ex2', level: 'extreme', category: 'IRR・投資分析', question: 'A物件（利回り8%・RC造・都市部）とB物件（利回り11%・木造・地方）を比較する際、リスク調整後リターンで優位性を判断する指標として最も適切なものはどれですか？', choices: ['表面利回りの単純比較', 'PER（Price Earnings Ratio）', '固定資産税評価額の比率', 'シャープレシオ（超過リターン÷標準偏差）'], correct: 3, explanation: 'シャープレシオはリスク1単位あたりの超過リターンを示します。不動産では空室率・修繕リスク・流動性リスクを標準偏差として近似し計算します。利回り差3%がリスク差を上回るかを定量評価できる点で、単純利回り比較より優れた判断基準です。' },
  { id: 'ex3', level: 'extreme', category: 'IRR・投資分析', question: '不動産投資のDCF（割引キャッシュフロー）法において「ターミナルキャップレート」が重要な理由として最も適切なものはどれですか？', choices: ['売却時の物件価値算定に直接影響し、DCF総額の大部分を左右するため', '毎年の家賃収入を割り引く際の基準率になるため', '修繕積立金の適正水準を算出するために使うため', '融資審査における担保評価の基準になるため'], correct: 0, explanation: 'DCF法では保有期間末の売却価格＝「最終年度NOI÷ターミナルキャップレート」で算出します。10年保有なら売却収入がTCFの40〜60%を占めることも多く、ターミナルキャップレートが0.5%変わるだけで物件価値が数百万〜数千万変動します。出口を見据えた投資判断の核心です。' },
  { id: 'ex4', level: 'extreme', category: 'IRR・投資分析', question: 'レバレッジ効果が「正」に働く条件として正しいものはどれですか？', choices: ['借入金利が固定金利で固定されている状態', '物件の総収益率（FCR）がローン定数（K%）を上回っている状態', '物件の表面利回りが実質利回りを上回っている状態', '自己資金比率が50%以下の状態'], correct: 1, explanation: 'FCR（Free and Clear Return）＝NOI÷総投資額。K%＝年間返済額÷借入金額。FCR＞K%の時レバレッジは正に働き、自己資金利回り（CCR）がFCRを上回ります。FCR＜K%になると負のレバレッジとなり、借入が収益を悪化させます。MBAで必須の不動産金融理論です。' },
  { id: 'ex5', level: 'extreme', category: 'IRR・投資分析', question: '「修正IRR（MIRR）」が通常のIRRより信頼性が高いとされる理由はどれですか？', choices: ['計算が単純でExcelを使わず手計算できるため', '物件の築年数を考慮した減価償却を織り込めるため', '途中のキャッシュフローを再投資する際の収益率を現実的な水準で仮定できるため', '金利変動リスクを自動的に中和できるため'], correct: 2, explanation: '通常のIRRは途中のCFをIRRと同じ高率で再投資できると仮定しており、高IRR物件ほど過大評価になります。MIRRは再投資収益率を安全資産利回り等の現実的な率で設定するため、複数物件比較の精度が上がります。機関投資家やPEファンドが好む指標です。' },
  { id: 'ex6', level: 'extreme', category: 'IRR・投資分析', question: 'NOI（純営業収益）とNCF（純キャッシュフロー）の違いとして正しいものはどれですか？', choices: ['NOIは税引き後・NCFは税引き前の収益を示す', 'NCFはNOIに減価償却費を加算した会計上の利益', 'どちらも同じ概念で不動産業界では混用されている', 'NCFはNOIから資本的支出（CapEx）と元金返済を差し引いた実際の手残り'], correct: 3, explanation: 'NOI＝総収入－運営費用（ローン返済・減価償却除く）。NCF＝NOI－資本的支出（屋根・設備の大規模修繕等）。さらにDCF分析ではNCFからローン元金返済を引いたAfter-Tax CFも重要です。NOIだけで判断すると修繕費を見落とす危険があります。' },
  { id: 'ex7', level: 'extreme', category: '融資戦略', question: '「積算評価」が低い物件への融資を引き出すために実務で使われる戦略として最も適切なものはどれですか？', choices: ['収益還元評価（DCF法）を重視するノンバンクや信金を活用する', '自己資金をゼロにしてフルローンを狙う', '物件価格を意図的に高く申告して積算評価を上げる', '固定金利を選択して銀行の不安を払拭する'], correct: 0, explanation: 'メガバンクや地銀は積算評価重視ですが、信用金庫・ノンバンク・一部地方銀行は収益性（DCF・NOI）重視の評価をします。エリア・築年・構造によって相性の良い金融機関が異なります。融資に詳しいブローカー活用も有効です。' },
  { id: 'ex8', level: 'extreme', category: '融資戦略', question: '「デット・サービス・カバレッジ・レシオ（DSCR）」が1.2以上を融資条件とする銀行において、NOI600万円の物件で最大借入可能な年間返済額はいくらですか？', choices: ['600万円', '500万円', '720万円', '480万円'], correct: 1, explanation: 'DSCR＝NOI÷年間返済額。DSCR≥1.2の条件より、年間返済額≤NOI÷1.2＝600÷1.2＝500万円。DSCRは不動産投資ローンの審査で最重要指標の一つ。1.0を切ると返済不能、1.2〜1.3が銀行の安全ラインとされます。' },
  { id: 'ex9', level: 'extreme', category: '融資戦略', question: '「土地値物件（土地評価＞物件価格）」が投資家に好まれる理由として最も正確なものはどれですか？', choices: ['家賃収入が必ず高くなるため表面利回りが上がる', '固定資産税が軽減されるため実質コストが下がる', '建物が無価値になっても土地担保で融資・売却が容易なため出口リスクが低い', '再建築時に容積率が自動的に緩和されるため'], correct: 2, explanation: '土地値物件は建物が老朽化・無価値になっても土地売却で投資回収できる出口保険。特に都市部では土地需要が底堅く、最悪でも「更地売却」という選択肢があります。積算評価が高いため融資も受けやすく、プロ投資家が最重視する概念の一つです。' },
  { id: 'ex10', level: 'extreme', category: '融資戦略', question: 'ブリッジローンを不動産投資で活用する場面として最も適切なものはどれですか？', choices: ['変動金利から固定金利に切り替える際の移行期間', '修繕積立金が不足した場合の緊急資金調達', '確定申告で赤字が出た年の税務対策', '競売物件など長期融資実行前に短期つなぎ資金が必要な場合'], correct: 3, explanation: 'ブリッジローン（つなぎ融資）は長期融資実行までの短期調達手段。競売・任意売却など決済スピードが求められる場面、リフォーム完了後に通常融資に借り換えるケース等で活用します。金利は高め（年4〜10%）ですが、収益機会を逃さない戦略的ツールです。' },
  { id: 'ex11', level: 'extreme', category: '融資戦略', question: '金融機関が「属性」として評価する要素のうち、不動産投資融資審査で最もプラスに働く組み合わせはどれですか？', choices: ['上場企業勤務・年収1,000万円以上・金融資産2,000万円以上・他借入少ない', '自営業・年収500万円・不動産投資歴10年・所有物件多数', '公務員・年収400万円・貯蓄ゼロ・他ローンなし', '医師・年収2,000万円・開業資金借入あり・不動産投資未経験'], correct: 0, explanation: '銀行は安定収入（上場企業・公務員）・年収・金融資産・借入状況を総合評価します。年収1,000万円超・金融資産2,000万円超・他借入少は最高属性。医師は年収高くても開業借入が減点要因に。自営業は安定性が低く評価されやすい傾向があります。' },
  { id: 'ex12', level: 'extreme', category: '税務・法人化', question: '個人所有から法人所有への「法人化」を検討すべき所得の目安として実務上よく言われる水準はどれですか？', choices: ['不動産収入が年間1,000万円を超えたら必ず法人化が有利', '課税所得が900万円を超えるあたりから法人化のメリットが生じやすい', '物件数が10棟を超えたら法人化が義務になる', '所得に関わらず最初から法人化すべき'], correct: 1, explanation: '個人の所得税率は課税所得900万円超で33%（住民税込み43%）となり、法人税実効税率（約23〜30%）を超えます。ただし法人設立コスト・社会保険負担・税理士費用等も発生するため、総合的なシミュレーションが必要です。' },
  { id: 'ex13', level: 'extreme', category: '税務・法人化', question: '不動産の「減価償却」を活用した節税スキームの限界として正しいものはどれですか？', choices: ['減価償却費は現金支出なので節税効果はない', '土地も建物も同様に減価償却できる', '償却期間終了後は経費計上できなくなりデッドクロスが深刻化する', '法人は減価償却を使えないため個人所有が有利'], correct: 2, explanation: '減価償却は非現金費用で会計上の損失を作り課税所得を圧縮できます。しかし耐用年数経過後は償却費がゼロとなる一方、元金返済は続くためデッドクロスが深刻化します。木造22年・RC47年が法定耐用年数。築古物件は短期償却で節税効果大ですが出口も考慮が必要です。' },
  { id: 'ex14', level: 'extreme', category: '税務・法人化', question: '「短期譲渡所得」と「長期譲渡所得」の税率の違いとして正しいものはどれですか？', choices: ['所有3年以下が短期で税率50%・3年超が長期で税率15%', '法人所有の場合は短期・長期の区別がなく一律30%', '短期と長期の税率差は5%程度で実質的な影響は小さい', '所有5年以下の短期は約39%・5年超の長期は約20%（いずれも個人・住民税込み）'], correct: 3, explanation: '個人の不動産譲渡税：短期（5年以下）＝所得税30%＋住民税9%＝約39%、長期（5年超）＝所得税15%＋住民税5%＝約20%。この差は巨大で、例えば利益3,000万円なら短期1,170万・長期600万と570万円の差。売却タイミングは5年超を基本戦略にすべき理由です。' },
  { id: 'ex15', level: 'extreme', category: '税務・法人化', question: '「消費税還付スキーム」が不動産投資で難しくなった主な理由はどれですか？', choices: ['2020年の税制改正で取得期に課税売上を作る手法が封じられたため', '消費税率が10%に上がり還付額が大きすぎて国が廃止したため', '不動産賃貸は元々消費税の課税対象外のため還付対象にならないため', '法人のみ対象で個人事業主には最初から適用されなかったため'], correct: 0, explanation: '住宅賃貸は消費税非課税のため、原則として消費税還付は受けられません。以前は「自動販売機設置で課税売上を作る」等の手法がありましたが、2020年の税制改正（高額特定資産の仕入税額控除制限）で実質封じられました。現在は合法的な還付スキームの適用は困難です。' },
  { id: 'ex16', level: 'extreme', category: '税務・法人化', question: '不動産投資法人（SPC）における「倒産隔離」の主な目的として正しいものはどれですか？', choices: ['法人税を完全にゼロにするための租税回避スキームのため', '親会社・スポンサーが経営危機に陥っても対象不動産への影響を遮断するため', '銀行融資の金利を強制的に引き下げるための交渉手段のため', '不動産の登記を省略して取引コストを削減するため'], correct: 1, explanation: 'SPCによる倒産隔離はJ-REITや不動産証券化の根幹概念。スポンサー企業が破綻しても当該不動産を守り、投資家・金融機関を保護します。一般的な法人化とは異なり、資産流動化法に基づく高度な法的スキームです。' },
  { id: 'ex17', level: 'extreme', category: '税務・法人化', question: '「小規模宅地等の特例」を不動産投資と相続対策に活用する場合の限度面積として正しいものはどれですか？', choices: ['貸付事業用宅地は330㎡まで80%評価減', '居住用と事業用を合算して500㎡まで適用可能', '貸付事業用宅地は200㎡まで50%評価減', '建物がある土地のみ適用で更地には使えない'], correct: 2, explanation: '小規模宅地の特例：貸付事業用は200㎡まで50%評価減、特定事業用・特定居住用は330㎡まで80%評価減。相続税対策として不動産投資が有効とされる根拠の一つ。ただし三年以内に取得した貸付事業用宅地は適用除外（2018年改正）。相続専門税理士との連携が必須です。' },
  { id: 'ex18', level: 'extreme', category: '出口戦略', question: '「オポチュニスティック投資」の特徴として最も正しいものはどれですか？', choices: ['安定稼働中の優良物件に低リスクで投資するコア戦略', 'インフレヘッジを主目的とした長期保有型投資', '政府系ファンドが好む低利回り・超安定型の投資スタイル', '高リスク・高リターンを狙う開発・再生型投資でIRR20%以上を目標とする'], correct: 3, explanation: '不動産投資戦略はリスク/リターンでコア（利回り4〜6%）・コアプラス（6〜10%）・バリューアッド（10〜15%）・オポチュニスティック（15〜20%超）に分類されます。オポチュニスティックは空き家再生・用途転換・不良債権処理など高度な専門性が必要です。' },
  { id: 'ex19', level: 'extreme', category: '出口戦略', question: '人口減少地域の収益物件の出口として「収益還元価格より積算価格が上回る物件」を選ぶ理由として最も適切なものはどれですか？', choices: ['賃貸需要が消えても土地・建物の実物価値で売却できる最終的な安全網になるため', '積算価格が高い物件は家賃も高く設定できるため', '積算評価の高い物件は固定資産税が安くなるため', '収益還元価格より積算価格が高い物件は融資が通らないため買い手がいない'], correct: 0, explanation: '人口減少地域では将来的に収益性（家賃収入）が低下するリスクがあります。その場合でも積算価格（土地＋建物の実物評価）が物件価格を上回っていれば、最悪「解体・更地売却」という出口が残ります。収益性と積算の両軸で評価するのがプロの手法です。' },
  { id: 'ex20', level: 'extreme', category: '出口戦略', question: '不動産の「パッケージ売却」が個別売却より高値になるケースとして最も適切なものはどれですか？', choices: ['同一エリアの物件を全て別々の個人投資家に分散売却する場合', '複数棟をポートフォリオとして機関投資家やREITに一括売却する場合', '物件を区分所有に分割して小口化し一般投資家に売る場合', '築古物件を解体して更地にしてから売却する場合'], correct: 1, explanation: 'REITや機関投資家は規模の経済・管理効率・分散効果を評価します。例えば総額50億円のポートフォリオは個別売却の合計より5〜15%高値がつくことも。これを「ポートフォリオプレミアム」と呼びます。大規模投資家との出口戦略を視野に入れた物件選びが重要です。' },
  { id: 'ex21', level: 'extreme', category: '出口戦略', question: '「キャップレートの圧縮」が投資リターンにどう影響するか、最も正しい説明はどれですか？', choices: ['キャップレートが下がると利回りが上昇し、投資効率が改善する', 'キャップレートの変動はNOIに影響しないため売却価格と無関係', 'キャップレートが下がると物件価格が上昇し、保有中に売却すれば含み益が得られる', 'キャップレートは固定されていて市場環境で変化しない'], correct: 2, explanation: '物件価格＝NOI÷キャップレート。例えばNOI300万円の物件でキャップレートが5%→4%に圧縮されると価格は6,000万→7,500万円に1,500万円上昇します。低金利環境ではキャップレート圧縮が起きやすく、これを「キャップレート圧縮益」として狙うのが機関投資家の戦略です。' },
  { id: 'ex22', level: 'extreme', category: '出口戦略', question: 'ホテル・商業施設への「用途転換（コンバージョン）」投資で最重要となる法規制はどれですか？', choices: ['宅地建物取引業法の免許取得', '国土利用計画法の土地取引届出', '農地法の転用許可', '建築基準法の用途変更確認申請（床面積200㎡超は確認申請が必要）'], correct: 3, explanation: '用途変更はオフィス→ホテル・工場→マンション等の転換投資。延べ面積200㎡超の建物は建築確認申請が必要で、用途ごとの耐火・避難・設備基準をクリアしなければなりません。構造補強コストが膨大になるケースも。法規制の事前調査が収益計画の生命線です。' },
  { id: 'ex23', level: 'extreme', category: '再建築不可', question: '「再建築不可物件」への融資を実現する方法として実務上使われるものはどれですか？', choices: ['ノンバンクの不動産担保ローンまたは隣地買収による接道義務クリア', '国土交通大臣への特別許可申請で再建築を認可してもらう', '固定資産税評価額を下げる申請をして担保評価を上げる', '再建築不可物件は法律上一切の融資が禁止されている'], correct: 0, explanation: '再建築不可（接道幅2m未満等）は通常銀行融資が難しいですが、ノンバンクは担保評価次第で融資可能です。根本的な解決策は隣地（私道含む）を買収・賃借して接道義務をクリアする方法。セットバックや43条但し書き申請も選択肢です。' },
  { id: 'ex24', level: 'extreme', category: '再建築不可', question: '「容積率の未消化（容積率消化率が低い物件）」を活用した投資戦略として最も適切なものはどれですか？', choices: ['容積率が低い方が固定資産税が安くなるため保有コストが下がる', '増築・建替えで床面積を増やし収益を向上させるバリューアッド戦略', '容積率未消化物件は必ず再建築不可なので購入を避けるべき', '容積率は建物の高さに関する規制で賃貸収入と無関係'], correct: 1, explanation: '容積率消化率が低い（例：指定容積率300%に対し現状100%）物件は、建替えや増築で収益を2〜3倍にできるポテンシャルを秘めています。これを「容積率余剰」といい、開発系投資家が高値で購入する対象。現況利回りより土地の開発ポテンシャルで評価します。' },
  { id: 'ex25', level: 'extreme', category: '再建築不可', question: '「既存不適格建築物」と「違反建築物」の違いとして正しいものはどれですか？', choices: ['既存不適格は修繕が禁止され、違反建築は修繕が義務付けられる', '両者とも銀行融資は一切受けられない', '既存不適格は建設時は合法だったが法改正で現行基準に不適合になった建物、違反建築は当初から法令違反で建てられた建物', '既存不適格は個人所有のみで、違反建築は法人所有の物件に限られる'], correct: 2, explanation: '既存不適格建築物は現行法に不適合でも使用継続が認められます（建替え時は現行基準適用）。銀行融資も可能なケースが多い。一方、違反建築（無確認建築・確認申請と異なる建物）は是正命令対象で融資が困難。購入前の確認申請書・検査済証の確認が必須です。' },
  { id: 'ex26', level: 'extreme', category: '再建築不可', question: '「生産緑地2022年問題」が不動産市場に与えた影響として実際に起きたこととして正しいものはどれですか？', choices: ['東京23区内で2022年に大量の農地が宅地化されマンション価格が暴落した', '生産緑地指定が全て解除され固定資産税が100倍になった', '政府が生産緑地を全て買い上げ国有地として公園化した', '2022年の期限延長制度（特定生産緑地）により大規模な宅地供給は起きなかった'], correct: 3, explanation: '1992年に指定された生産緑地（30年縛り）が2022年に期限を迎え「大量宅地供給による地価暴落」が懸念されました。しかし特定生産緑地制度による10年延長申請が広く活用され、大規模な供給増は起きませんでした。不動産市場への影響予測と実態の乖離を示す好例です。' },
  { id: 'ex27', level: 'extreme', category: '相続・資産承継', question: '不動産を活用した相続税対策として「タワーマンション節税」が規制された理由はどれですか？', choices: ['固定資産税評価額（時価の2〜3割）と市場価格の乖離を利用した過度な節税に規制が入ったため', 'タワーマンションは危険建築物として相続財産から除外されたため', '相続後3年以内に売却した場合の税率が引き上げられたため', '2024年以降タワーマンションの新規建設が禁止されたため'], correct: 0, explanation: 'タワマン節税：高層階は市場価格が高くても固定資産税評価額（＝相続税評価額）は低層階とほぼ同じため、時価10億円の部屋が2億円で評価されるケースがありました。2024年から高層階補正（階数×0.33%加算）が導入され節税効果が縮小。評価の適正化が図られています。' },
  { id: 'ex28', level: 'extreme', category: '相続・資産承継', question: '「相続時精算課税制度」を不動産の生前贈与に活用する際のリスクとして正しいものはどれですか？', choices: ['相続時精算課税は不動産には適用できない', '一度選択すると暦年贈与に戻せず、相続時に全額精算されるため値上がり資産には不利になる場合がある', '2,500万円を超える贈与には一律50%の税率が課せられる', '選択後は5年以内に相続が発生すると全額没収される'], correct: 1, explanation: '相続時精算課税は2,500万円まで贈与税ゼロ（超過分は20%）で贈与でき、相続時に精算します。2024年改正で年110万円控除も追加。ただし贈与後に資産価値が上昇した場合、贈与時の価格で精算されるため損になります。値下がりリスクのある資産への活用が有効です。' },
  { id: 'ex29', level: 'extreme', category: '相続・資産承継', question: '不動産法人の「株式承継」と「不動産直接承継」を比較した場合の株式承継のメリットとして正しいものはどれですか？', choices: ['株式承継の方が相続税評価額が必ず低くなる', '株式は非上場のため相続税の対象外になる', '不動産取得税・登録免許税が不要で承継コストが大幅に削減できる', '銀行融資の引継ぎが不要になる'], correct: 2, explanation: '不動産を直接相続・贈与すると不動産取得税（3〜4%）と登録免許税（2%）が発生します。法人化して株式で承継すれば不動産の名義変更が不要でこれらのコストを回避できます。ただし株式の相続税評価（類似業種比準・純資産価額）の計算は複雑で専門家関与が必須です。' },
  { id: 'ex30', level: 'extreme', category: '相続・資産承継', question: '「家族信託（民事信託）」を不動産に活用する主な目的として最も適切なものはどれですか？', choices: ['相続税を完全にゼロにするための節税スキーム', '不動産の共有状態を解消して単独所有に変換するため', '銀行融資の保証人を不要にするための法的手続き', '認知症等で判断能力が低下した場合でも受託者が不動産管理・処分を継続できるようにするため'], correct: 3, explanation: '家族信託は委託者（オーナー）が信頼できる家族（受託者）に財産管理を託す仕組み。オーナーが認知症になっても受託者が賃貸管理・売却・修繕の意思決定を継続できます。成年後見制度と異なり柔軟な財産管理が可能。2024年以降急速に普及している資産承継ツールです。' },
];

export const drillLevel2 = [
  { id: 101, level: 2, category: 'キャッシュフロー', question: '月額家賃15万円・管理費1万円・修繕積立1万円・ローン返済9万円の物件の月間キャッシュフローはいくらですか？', choices: ['4万円', '6万円', '5万円', '3万円'], correct: 0, explanation: 'CF = 家賃 - 管理費 - 修繕積立 - ローン返済 = 15 - 1 - 1 - 9 = 4万円。キャッシュフロー計算は「手元に残る実際のお金」を把握するための基本です。' },
  { id: 102, level: 2, category: 'キャッシュフロー', question: 'キャッシュフロー利回り（CCR）の計算式として正しいものはどれですか？', choices: ['年間家賃収入 ÷ 物件価格 × 100', '年間キャッシュフロー ÷ 自己資金 × 100', 'NOI ÷ 物件価格 × 100', '年間返済額 ÷ 借入金 × 100'], correct: 1, explanation: 'CCR（Cash on Cash Return）= 年間CF ÷ 自己資金 × 100。自己資金に対する実際の回収率を示す重要指標です。' },
  { id: 103, level: 2, category: 'キャッシュフロー', question: '「税引き前キャッシュフロー」と「税引き後キャッシュフロー」の違いとして正しいものはどれですか？', choices: ['税引き前は家賃収入のみで経費を引く前の金額', '両者は同じ意味で使われる', '税引き後は所得税・住民税を差し引いた手取り金額', 'ローン返済を含むかどうかの違い'], correct: 2, explanation: '税引き後CFは確定申告後に実際に手元に残る金額。不動産所得が発生すると所得税・住民税が課されるため、実質的な手残りは税引き前より少なくなります。' },
  { id: 104, level: 2, category: 'キャッシュフロー', question: '空室率10%・月額家賃20万円・年間経費60万円・年間ローン返済180万円の場合、年間キャッシュフローはいくらですか？', choices: ['+24万円', '0万円', '+60万円', '−24万円'], correct: 3, explanation: '年間収入 = 20万 × 12 × 0.9 = 216万円。CF = 216 - 60 - 180 = -24万円。空室率を加味すると赤字になるケースは多い。購入前のシミュレーションが重要です。' },
  { id: 105, level: 2, category: 'キャッシュフロー', question: 'キャッシュフローが「プラスだが少ない」物件を保有し続けるメリットとして最も適切なものはどれですか？', choices: ['ローン残高が減り資産が積み上がる', '即座に大きな収益を得られる', '税金が完全にゼロになる', '管理の手間がなくなる'], correct: 0, explanation: '毎月のCFが少額でも、ローン元金返済によって純資産（物件価値 - ローン残高）は確実に増加します。これをエクイティ積み上げ効果といい、長期投資の重要な収益源です。' },
  { id: 106, level: 2, category: 'キャッシュフロー', question: '「繰り上げ返済」がキャッシュフローに与える影響として正しいものはどれですか？', choices: ['返済期間短縮型は月々のCFは変わらないが総利息が減る', '返済額軽減型は毎月のCFが改善する', '繰り上げ返済はCFに一切影響しない', '繰り上げ返済すると利回りが上がる'], correct: 1, explanation: '返済額軽減型の繰り上げ返済は毎月の返済額を減らすためCFが改善します。返済期間短縮型は返済額は変わりませんが総利息が減り、長期的な収益向上につながります。' },
  { id: 107, level: 2, category: 'キャッシュフロー', question: 'NOI（純営業収益）の計算式として正しいものはどれですか？', choices: ['年間家賃収入 − ローン返済額', '年間家賃収入 − 全経費', '年間家賃収入 − 運営費用（ローン・減価償却除く）', '年間家賃収入 × 実質利回り'], correct: 2, explanation: 'NOI = 総収入 - 運営費用（管理費・修繕費・税金・保険料等）。ローン返済と減価償却は含みません。物件の収益力を借入条件に左右されず評価する指標です。' },
  { id: 108, level: 2, category: 'キャッシュフロー', question: '「潜在総収入（GPI）」と「実効総収入（EGI）」の違いはどれですか？', choices: ['GPIは実際の収入でEGIは理論値', '両者に違いはない', 'EGIはGPIより必ず高くなる', 'EGIはGPIから空室損失と未収損失を引いた実際の収入'], correct: 3, explanation: 'GPI（Gross Potential Income）= 満室想定の年間家賃収入。EGI（Effective Gross Income）= GPI - 空室損失 - 未収家賃損失。EGIの方がより実態に近い収入指標です。' },
  { id: 109, level: 2, category: 'キャッシュフロー', question: 'キャッシュフローを改善する方法として最も効果的なものはどれですか？', choices: ['家賃の値上げ・空室率の低下・経費削減・金利交渉の組み合わせ', '物件をすぐに売却する', '管理会社を月1回変更する', '修繕を一切行わない'], correct: 0, explanation: 'CFの改善には収入増加（家賃UP・空室率低下）と支出削減（経費削減・金利交渉・繰り上げ返済）の両面からのアプローチが効果的。単一施策より複合的な改善が重要です。' },
  { id: 110, level: 2, category: 'キャッシュフロー', question: '「プロフォーマ（Pro Forma）」とは不動産投資でどのような意味ですか？', choices: ['過去の収支実績をまとめた報告書', '将来の収支を予測した事業計画書', '建物の設計図面のこと', '融資申込時の必要書類一式'], correct: 1, explanation: 'プロフォーマは取得前に作成する将来収支の予測モデル。家賃収入・空室率・経費・ローン返済・CF・利回りを複数シナリオで試算します。投資判断の中核となる資料です。' },
  { id: 111, level: 2, category: '金利・融資', question: '変動金利ローンの「5年ルール」と「125%ルール」の意味として正しいものはどれですか？', choices: ['5年ごとに金利が必ず上がり125%まで上昇する', '5年後に元金の125%を一括返済する', '5年間は返済額が変わらず、変更後も前回の125%を上限とする', '金利が5%を超えたら125万円の補填がある'], correct: 2, explanation: '多くの銀行の変動金利では①5年間は返済額を据え置き②次の5年間の返済額は前回の最大125%まで。金利急上昇時にも急激な返済増を防ぐ仕組みですが、未払い利息が発生するリスクもあります。' },
  { id: 112, level: 2, category: '金利・融資', question: 'オーバーローン（Over Loan）の意味として正しいものはどれですか？', choices: ['金利が相場より高いローンのこと', '複数の物件に同時にローンを組むこと', '返済期間が35年を超えるローンのこと', '借入金が物件の担保価値（積算評価）を超えている状態'], correct: 3, explanation: 'オーバーローンは借入額が物件の担保評価額を超える状態。売却しても借金が残るリスクがあります。特に新築ワンルームマンション投資で起きやすく、注意が必要です。' },
  { id: 113, level: 2, category: '金利・融資', question: '「アパートローン」と「プロパーローン」の主な違いはどれですか？', choices: ['プロパーは個別審査・高額融資可能、アパートローンはパッケージ商品で審査がシンプル', 'アパートローンは法人専用でプロパーは個人専用', 'プロパーは金利が必ず低い', 'アパートローンは住宅ローンの一種'], correct: 0, explanation: 'アパートローンは銀行が用意した標準化商品で審査が比較的シンプル。プロパーローンは個別案件として審査し、大型物件や複雑な案件に対応可能。金利・期間・条件は交渉次第で変わります。' },
  { id: 114, level: 2, category: '金利・融資', question: '借入金利2.5%・返済期間30年・借入額3,000万円の月返済額として最も近いものはどれですか？', choices: ['約8.3万円', '約11.8万円', '約14.2万円', '約9.5万円'], correct: 1, explanation: '元利均等返済の計算：月利=2.5/12/100≒0.208%。月返済額≒3,000万×[0.00208×(1.00208)^360]/[(1.00208)^360-1]≒11.8万円。概算で借入額×0.4%/月が目安です。' },
  { id: 115, level: 2, category: '金利・融資', question: 'ノンバンクからの融資が「銀行融資と比べて高コスト」とされる理由として正しいものはどれですか？', choices: ['ノンバンクは返済期間が短く月返済が少ないため', 'ノンバンクの方が必ず低金利なため', '金利が高く手数料も高いが審査基準が柔軟なため', '審査が厳しく信頼性が高いため'], correct: 2, explanation: 'ノンバンクは銀行に比べ金利3〜8%と高く手数料も多い一方、築古・再建築不可・低積算など銀行が敬遠する物件にも融資します。費用対効果を十分計算した上での活用が必要です。' },
  { id: 116, level: 2, category: '金利・融資', question: '「融資期間を長くする」ことで発生するトレードオフとして正しいものはどれですか？', choices: ['月返済が増えCFが悪化するが資産形成が早まる', '融資期間と総利息は無関係', '期間を長くすると金利が下がる', '月返済は減りCFは改善するが総利息支払いが増える'], correct: 3, explanation: '融資期間を長くすると月返済額が下がりCFが改善しますが、長期間にわたり利息を払い続けるため総支払額は増加します。CFとトータルコストのバランスを考えた期間設定が重要です。' },
  { id: 117, level: 2, category: '金利・融資', question: '「金利スワップ」を不動産投資で活用する目的として最も適切なものはどれですか？', choices: ['変動金利ローンを固定金利に交換してキャッシュフローを安定させる', '複数の物件を一つのローンにまとめる', '金利差益を得るための投機的取引', '借入額を増やすための手法'], correct: 0, explanation: '金利スワップは変動金利ローンの金利変動リスクをヘッジする手法。変動を固定に「交換」することでCFの予測可能性が上がります。主に大型商業用不動産や機関投資家が活用します。' },
  { id: 118, level: 2, category: '金利・融資', question: '住宅金融支援機構の「フラット35」が投資用物件に使えない理由はどれですか？', choices: ['金利が高すぎて投資に向かないため', 'フラット35は本人が居住する住宅のみに適用されるため', '申込資格が会社員に限定されているため', 'フラット35は土地のみにしか使えないため'], correct: 1, explanation: 'フラット35は住宅ローンの一種で、申込者本人または家族が居住することが条件。投資用賃貸物件に使用すると規約違反となり、一括返済を求められる場合があります。' },
  { id: 119, level: 2, category: '金利・融資', question: '「負債比率（D/E比率）」が投資家にとって重要な理由はどれですか？', choices: ['物件の収益性を直接示す指標のため', '管理会社の評価に使われる指標のため', '自己資本に対する借入の割合を示し、財務レバレッジのリスクを測る指標のため', '税務申告で必須の計算式のため'], correct: 2, explanation: 'D/E比率 = 有利子負債 ÷ 自己資本。高いほどレバレッジが効いている一方でリスクも高い。収入減少や金利上昇時に債務不履行リスクが高まります。銀行の追加融資判断にも使われます。' },
  { id: 120, level: 2, category: '管理費・経費', question: '不動産投資で「減価償却費」が節税効果をもたらす仕組みとして正しいものはどれですか？', choices: ['毎年現金が戻ってくる還付制度', '固定資産税が免除される制度', 'ローン利息を経費にできる制度', '現金支出なしに経費計上でき、課税所得を減らせる'], correct: 3, explanation: '減価償却は建物の劣化を費用として計上する会計処理。実際の現金支出はないが帳簿上の経費として課税所得を圧縮できます。ただし償却期間終了後はこの効果がなくなります。' },
  { id: 121, level: 2, category: '管理費・経費', question: '木造建物の法定耐用年数は何年ですか？', choices: ['22年', '34年', '47年', '15年'], correct: 0, explanation: '法定耐用年数：木造22年・軽量鉄骨（3mm以下）19年・軽量鉄骨（3〜4mm）27年・重量鉄骨34年・RC造47年。耐用年数が短いほど年間の減価償却費が大きくなり節税効果が高まります。' },
  { id: 122, level: 2, category: '管理費・経費', question: '「資本的支出」と「修繕費（収益的支出）」の違いとして正しいものはどれですか？', choices: ['修繕費は大きな金額で資本的支出は少額の支出', '資本的支出は資産価値を高める支出で減価償却必要、修繕費は現状回復で全額即時経費', '両者とも全額即時に経費計上できる', '資本的支出は税務署に申告不要'], correct: 1, explanation: '資本的支出（エレベーター設置・増改築等）は固定資産として計上し減価償却が必要。修繕費（壁紙貼替・故障修理等）は全額その年の経費として計上可能。判定基準は税務調査でも争点になりやすい重要事項です。' },
  { id: 123, level: 2, category: '管理費・経費', question: '不動産投資において「損益通算」が有効な場合とはどのような状況ですか？', choices: ['利益が出たときに他の損失と相殺できる', '複数の物件間で利益と損失を自由に移転できる', '不動産所得が赤字のとき、給与所得等と合算して税金を減らせる', '損失が出たら税務署から補填される'], correct: 2, explanation: '損益通算は不動産所得の赤字を給与所得等から差し引き、課税所得全体を圧縮する節税手法。ただしサラリーマン大家の場合、土地取得ローン利息部分は損益通算が制限されます。' },
  { id: 124, level: 2, category: '管理費・経費', question: '管理委託費を実質利回り計算に含める際の目安として正しいものはどれですか？', choices: ['物件価格の1%を毎月計上する', '管理費は経費に含めなくてよい', '年間家賃の50%を管理費として計上する', '家賃収入の5〜10%を管理費として計上する'], correct: 3, explanation: '管理委託費の相場は賃貸管理で家賃の5〜10%。この費用を含めずに実質利回りを計算すると実態より高い数字になります。サブリース（家賃保証）では10〜15%程度引かれるケースもあります。' },
  { id: 125, level: 2, category: '管理費・経費', question: '固定資産税・都市計画税の課税基準として正しいものはどれですか？', choices: ['固定資産税評価額（時価の60〜70%程度）に税率をかけて算出', '取得価格に税率1.4%をかけて算出', '毎年の家賃収入に税率をかけて算出', '路線価に面積をかけて算出'], correct: 0, explanation: '固定資産税 = 固定資産税評価額 × 1.4%。都市計画税 = 同評価額 × 0.3%（上限）。評価額は時価の60〜70%程度が一般的。住宅用地には課税標準の特例（1/6または1/3）があります。' },
  { id: 126, level: 2, category: '管理費・経費', question: '不動産投資で経費計上できるものとして正しいものはどれですか？', choices: ['ローン元金・生活費・趣味の費用', 'ローン利息・管理費・修繕費・固定資産税・損害保険料・交通費（物件管理目的）', '自宅の光熱費全額', '個人の医療費'], correct: 1, explanation: 'ローン利息（元金は不可）・管理費・修繕費・固定資産税・火災保険料・物件管理目的の交通費・通信費・税理士費用等が経費計上可能。プライベートと事業を明確に分けることが重要です。' },
  { id: 127, level: 2, category: '管理費・経費', question: '「青色申告特別控除」を不動産投資で受けるための条件として正しいものはどれですか？', choices: ['物件を1つ所有していれば自動的に適用', '確定申告さえすれば控除が受けられる', '事業的規模（5棟10室以上）で青色申告承認申請し複式簿記で記帳', '白色申告でも65万円控除を受けられる'], correct: 2, explanation: '不動産投資での65万円青色申告特別控除には①事業的規模（アパート5棟以上または10室以上）②青色申告承認申請③複式簿記による記帳④e-Taxまたは電子帳簿保存が必要です。' },
  { id: 128, level: 2, category: 'エリア分析', question: '投資用不動産のエリア選定で「人口動態」が重要な理由として最も適切なものはどれですか？', choices: ['人口が多いと物件価格が自動的に上がるため', '人口動態は利回りに直接関係しないため', '人口が減少するとローンが通りやすくなるため', '人口増加エリアは賃貸需要が安定し空室リスクが低いため'], correct: 3, explanation: '賃貸需要は入居者人口に比例します。国立社会保障・人口問題研究所の将来推計人口で20〜30年後の人口を確認することが長期投資では必須。特に地方物件は人口減少リスクを必ず評価してください。' },
  { id: 129, level: 2, category: 'エリア分析', question: '「駅徒歩分数」が賃貸需要に与える影響として最も正確なものはどれですか？', choices: ['徒歩10分以内は需要が安定し11分以上になると急激に需要が落ちる傾向がある', '駅からの距離は賃貸需要にほとんど影響しない', '徒歩30分でも需要は変わらない', '駅近は騒音が多く敬遠される'], correct: 0, explanation: '一般的に徒歩10分（約800m）が賃貸需要の分岐点。SUUMOの検索条件でも「10分以内」が最多選択。ただし商業エリアや大学周辺など立地特性によって異なります。' },
  { id: 130, level: 2, category: 'エリア分析', question: '「工業地域」に近い物件の特徴として正しいものはどれですか？', choices: ['工業地域は最も住みやすいエリアとして人気が高い', '工場勤務者需要はあるが騒音・臭気リスクがあり居住者層が限られる', '工業地域では住宅の建設が禁止されている', '工業地域は固定資産税が免除される'], correct: 1, explanation: '工業地域では住宅建設は可能ですが、準工業・工業専用に近いほど騒音・臭気のリスクが高まります。ただし工場従業員の賃貸需要があり、低価格で高利回りを狙える場合もあります。' },
  { id: 131, level: 2, category: 'エリア分析', question: '賃貸物件のターゲット入居者を分析する際に使う「賃貸需要マトリクス」の軸として適切なものはどれですか？', choices: ['物件価格と建物面積の組み合わせ', '利回りと築年数の組み合わせ', '家族構成（単身/ファミリー）と所得層（学生/社会人/富裕層）の組み合わせ', '管理会社と銀行の組み合わせ'], correct: 2, explanation: 'ターゲット分析では入居者の属性（単身/ファミリー、学生/社会人/高齢者）と所得層を掛け合わせ、そのニーズに合う物件スペック（間取り・設備・賃料）を逆算します。ターゲットを絞るほど空室対策が的確になります。' },
  { id: 132, level: 2, category: 'エリア分析', question: '「相場家賃」を調査する最も実践的な方法はどれですか？', choices: ['固定資産税評価額から計算する', '銀行の金利をもとに逆算する', '前オーナーの申告家賃をそのまま採用する', 'SUUMOやHOMES等で同エリア・同スペックの募集物件を複数比較する'], correct: 3, explanation: '相場家賃調査は不動産ポータルで実際の募集物件を比較するのが最も実践的。ただし掲載中の賃料は希望額であり、実際の成約賃料は5〜10%低い場合があります。管理会社への直接ヒアリングも有効です。' },
  { id: 133, level: 2, category: 'エリア分析', question: '地方都市への投資で「大学・病院・工場」の存在が重要視される理由はどれですか？', choices: ['安定した賃貸需要を生む「需要発生源」として機能するため', '物件価格が自動的に上昇するため', '固定資産税が優遇されるため', '管理会社が見つかりやすくなるため'], correct: 0, explanation: '大学は学生・教職員、病院は医療スタッフ・患者家族、工場は従業員の賃貸需要を継続的に生みます。これらが撤退・縮小すると需要が急減するリスクもあるため、移転・縮小リスクも合わせて調査が必要です。' },
  { id: 134, level: 2, category: 'エリア分析', question: '「新築物件が供給過多」のエリアに中古物件で投資する際のリスクとして正しいものはどれですか？', choices: ['中古は常に新築より需要が高いため問題ない', '新築との競争で家賃を下げざるを得なくなり利回りが低下するリスク', '新築が多いエリアは全体的に需要が高く問題ない', '供給過多は購入価格を上げる要因になる'], correct: 1, explanation: '新築供給過多エリアでは入居者が新築を選ぶため中古の賃料が下落圧力を受けます。特に地方都市での新築ワンルーム大量供給は中古市場全体を悪化させます。建築確認申請件数で今後の供給を事前に確認できます。' },
  { id: 135, level: 2, category: 'エリア分析', question: '「ハザードマップ」を投資物件選定に活用する主な理由はどれですか？', choices: ['ハザードマップが高リスクなほど利回りが高いため', 'ハザードマップは行政の義務で閲覧不要', '水害・地震等のリスクが高いエリアは保険料上昇・資産価値低下・入居者離れのリスクがあるため', '水害リスクは保険で完全にカバーできるため'], correct: 2, explanation: '2020年の宅建業法改正でハザードマップの重要事項説明が義務化。高リスクエリアは入居者の敬遠・保険料上昇・売却時の価格下落リスクがあります。国土交通省のハザードマップポータルで無料確認できます。' },
  { id: 136, level: 2, category: '固定/変動金利', question: '変動金利のメリットとして正しいものはどれですか？', choices: ['将来の返済額が確定していて資金計画が立てやすい', '金利上昇リスクが完全にない', '繰り上げ返済ができない', '金利低下時に恩恵を受けられ、初期の金利水準が固定より低い'], correct: 3, explanation: '変動金利は市中金利に連動して半年ごとに見直されます。金利低下局面では恩恵を受けられ、固定より初期金利が低い傾向があります。ただし金利上昇リスクを常に意識する必要があります。' },
  { id: 137, level: 2, category: '固定/変動金利', question: '固定金利が「変動金利より高い」理由として最も正確なものはどれですか？', choices: ['長期の金利変動リスクを銀行が負うためのリスクプレミアムが上乗せされているため', '固定金利の方が銀行の利益が少ないため低く設定される', '固定金利は政府が決定するため変動しない', '固定金利商品の審査が厳しいため'], correct: 0, explanation: '固定金利では銀行が長期にわたる金利変動リスクを負います。そのリスクプレミアムが上乗せされるため変動より高くなります。借主は「安心料」を払って金利リスクをヘッジしているといえます。' },
  { id: 138, level: 2, category: '固定/変動金利', question: '金融政策として「利上げ」が行われると変動金利はどうなりますか？', choices: ['固定金利が上がり変動金利は変化しない', '短期金利が上昇し変動金利ローンの金利が上がる傾向がある', '利上げは不動産ローンに影響しない', '変動金利は必ず下がる'], correct: 1, explanation: '変動金利は主に短期プライムレート（短プラ）に連動。日銀が政策金利を引き上げると短プラも上昇し変動金利ローンの金利が上がります。固定金利は長期国債利回りに連動するため別の動きをします。' },
  { id: 139, level: 2, category: '固定/変動金利', question: '「当初固定型（10年固定など）」のローンの特徴として正しいものはどれですか？', choices: ['一度固定したら完済まで金利は変わらない', '固定期間後は必ず金利が下がる', '固定期間終了後は変動または再固定を選択でき、当初金利は全期固定より低い', '当初固定型は住宅ローン専用で投資には使えない'], correct: 2, explanation: '当初固定型は一定期間（3・5・10年等）金利を固定し、期間終了後に変動か再固定を選択します。全期固定より当初金利が低く、キャッシュフロー計画を立てやすい特徴があります。' },
  { id: 140, level: 2, category: '固定/変動金利', question: '金利上昇局面で収益不動産投資家が取れる対策として正しいものはどれですか？', choices: ['金利上昇時は何もせず待てばよい', '新たに変動金利でローンを組む', '物件数を急増させてレバレッジを最大化する', '繰り上げ返済・固定金利への借り換え・家賃引き上げ交渉・低利物件の売却'], correct: 3, explanation: '金利上昇局面の対応：①繰り上げ返済で元本圧縮②固定への借り換えでリスクヘッジ③家賃見直しで収入増④CF悪化物件の売却・整理。事前にストレステスト（金利+1〜2%時のCF試算）をしておくことが重要です。' },
  { id: 141, level: 2, category: '固定/変動金利', question: 'ローンの「金利交渉」が有効な場合として最も適切なものはどれですか？', choices: ['返済実績が良好で他行からの条件提示がある場合、金利引き下げ交渉が有効', '金利交渉は一切効果がない', 'ローン残高が増えるほど交渉しやすい', '遅延した実績があるほど交渉力が増す'], correct: 0, explanation: '金利交渉は①長期良好な返済実績②他行からの条件提示（競合見積もり）③保有物件の価値上昇を材料に行います。特に他行の審査を通過した証拠があると交渉力が高まります。' },
  { id: 142, level: 2, category: '固定/変動金利', question: '「フラット35」の金利が決まる仕組みとして正しいものはどれですか？', choices: ['日銀の政策金利に連動して毎日変わる', '長期国債（10年物）の利回りを基準に毎月変動する', '取扱金融機関が自由に決定できる', '物件の築年数によって決まる'], correct: 1, explanation: 'フラット35の金利は住宅金融支援機構が発行する住宅ローン担保証券の利回りに連動し、長期国債利回りをベースに毎月見直されます。全期間固定のため完済まで返済額が変わりません。' },
  { id: 143, level: 2, category: '固定/変動金利', question: '不動産投資ローンでは住宅ローンに比べて金利が高い理由として正しいものはどれですか？', choices: ['投資ローンは国が保証しないため', '投資家は年収が高いため優遇が受けられないため', '居住用より事業リスクが高く担保回収が困難なケースがあるため', '投資ローンの審査が簡単すぎるため'], correct: 2, explanation: '住宅ローンは居住用で空室リスクがなく貸し倒れリスクが低い。投資ローンは空室・家賃下落・物件価値下落など事業リスクがあり銀行のリスクが高いため金利が高くなります。' },
  { id: 144, level: 2, category: '出口戦略', question: '不動産投資における「出口戦略」として考えられる選択肢はどれですか？', choices: ['売却のみが唯一の出口', '銀行への返還が出口', '相続税を支払って終了するのが出口', '売却・建て替え・リノベーション・民泊転用・法人への売却など複数の選択肢'], correct: 3, explanation: '出口戦略は①売却（個人・法人・投資家向け）②建て替えで資産価値向上③リノベーションでバリューアップ④民泊・シェアハウス転用⑤相続など複数あります。取得時から出口を想定した物件選びが重要です。' },
  { id: 145, level: 2, category: '出口戦略', question: '「含み損」状態の物件を売却すべきか保有すべきか判断する際の基準として正しいものはどれですか？', choices: ['今後のキャッシュフローと機会費用を比較して判断する', '含み損がある場合は必ず即売却すべき', '含み損でも保有し続けるべき', '税務上の都合だけで判断すべき'], correct: 0, explanation: '含み損物件でも毎月のCFがプラスで将来の価値回復が見込める場合は保有継続が有利な場合があります。逆にCFもマイナスなら損失拡大前に売却が合理的。感情ではなく数字で判断することが重要です。' },
  { id: 146, level: 2, category: '出口戦略', question: '物件を売却する際に「仲介」と「買取」の違いとして正しいものはどれですか？', choices: ['買取の方が必ず高値になる', '仲介は高値売却可能だが時間がかかる、買取は素早く売れるが価格が低くなる傾向', '仲介は即日売却できる', '買取と仲介は同じ意味'], correct: 1, explanation: '仲介は市場価格での売却が可能ですが3〜6ヶ月かかることも。買取は業者が直接購入するため最短数日で決済できますが市場価格の7〜8割程度になることが多いです。スピードと価格のトレードオフです。' },
  { id: 147, level: 2, category: '出口戦略', question: '「1棟もの」を売却する際に「収益還元法」で価格が決まる仕組みとして正しいものはどれですか？', choices: ['NOI × 建物面積 = 物件価格として計算される', '取得価格 × 築年数係数 = 物件価格として計算される', 'NOI ÷ キャップレート = 物件価格として計算される', '家賃 × 12ヶ月 = 物件価格として計算される'], correct: 2, explanation: '収益還元法：物件価格 = NOI ÷ キャップレート。例えばNOI300万円・キャップレート5%なら物件価格は6,000万円。売却時にNOIを上げる（満室経営・家賃UP）ことで売却価格を高めることができます。' },
  { id: 148, level: 2, category: '出口戦略', question: '「バリューアッド（Value-Add）戦略」の説明として正しいものはどれですか？', choices: ['購入後そのまま保有して自然な値上がりを待つ戦略', '初期投資を最小化して利回りを最大化する戦略', '複数の物件を同時に購入して分散投資する戦略', 'リノベーションや運営改善で物件価値を高めてから売却または高家賃化する戦略'], correct: 3, explanation: 'バリューアッド戦略は割安・課題ある物件を取得し、リノベ・テナント入替・管理改善等で価値を上げてから売却または賃料収入増を狙う手法。コア戦略より高リターンを目指せますが改善コストとリスクが伴います。' },
  { id: 149, level: 2, category: '出口戦略', question: '物件売却時に「譲渡費用」として計上できるものはどれですか？', choices: ['仲介手数料・測量費・建物取壊し費用・売却のための広告費用', '購入時のローン残高', '物件保有中の修繕費すべて', '売主の引越し費用'], correct: 0, explanation: '譲渡費用（売却時に計上できる経費）：仲介手数料・売買契約書印紙代・測量費・建物取壊し費・売却に直接要した費用等。取得費 + 譲渡費用が大きいほど課税対象の譲渡所得が圧縮できます。' },
  { id: 150, level: 2, category: '出口戦略', question: '「買い換え特例（事業用資産の買換え）」の活用条件として正しいものはどれですか？', choices: ['条件なく誰でも使える', '売却益の一部を新物件取得費に充て課税を繰り延べられるが条件が厳格', '居住用物件にのみ適用できる', '課税は繰り延べではなく完全免除になる'], correct: 1, explanation: '特定の事業用資産の買換え特例では、売却益の一定割合（最大80%）の課税を新物件取得年まで繰り延べできます。条件は①国内の事業用資産②一定の面積要件③1年以内の買換え等。税理士との連携が必須です。' },
];

export const drillLevel3 = [
  { id: 201, level: 3, category: 'IRR・DCF', question: 'IRR（内部収益率）が「最低要求収益率」を下回る投資案件はどう判断すべきですか？', choices: ['必ず投資すべき', 'IRRは参考値に過ぎず判断基準にならない', '投資価値なし（NPVがマイナスになるため経済的合理性がない）', '最低要求収益率を下げて対応すべき'], correct: 2, explanation: 'NPV法とIRR法は表裏一体。IRR > 最低要求収益率（ハードルレート）ならNPV>0で投資価値あり。IRR < ハードルレートならNPV<0で投資価値なし。機関投資家はIRR15〜20%をハードルにすることが多いです。' },
  { id: 202, level: 3, category: 'IRR・DCF', question: 'DCF法で「割引率」を決める考え方として最も適切なものはどれですか？', choices: ['固定で5%を使う', 'ローン金利をそのまま使う', '固定資産税率を割引率にする', '投資家の最低要求収益率（WACC等）を使い、リスクに応じて調整する'], correct: 3, explanation: '割引率はリスクを反映した「お金の時間価値」。不動産投資では借入コスト・自己資金コスト・リスクプレミアムを考慮したWACC（加重平均資本コスト）が理論的。実務では競合投資の機会費用を参考にすることも多いです。' },
  { id: 203, level: 3, category: 'IRR・DCF', question: 'DCF分析において「ターミナルバリュー」が大きくなる要因はどれですか？', choices: ['保有期間末のNOIが高く、ターミナルキャップレートが低い場合', 'NOIが低く保有期間が短い場合', 'ターミナルキャップレートが高いほどターミナルバリューは大きくなる', '割引率と同じ値になる場合'], correct: 0, explanation: 'ターミナルバリュー = 最終年度NOI ÷ ターミナルキャップレート。NOIが高いほど、キャップレートが低いほどターミナルバリューは大きくなります。10年保有では総DCFの40〜60%をターミナルバリューが占めることも多く、出口を慎重に設定する必要があります。' },
  { id: 204, level: 3, category: 'IRR・DCF', question: '「感応度分析（センシティビティ分析）」をDCFモデルで行う目的はどれですか？', choices: ['建物の耐震性を評価するため', '空室率・家賃・キャップレート等の変化がIRRやNPVに与える影響範囲を把握するため', '管理会社を選定するため', '税務申告の精度を上げるため'], correct: 1, explanation: '感応度分析は「もしも分析」。例えば空室率が5%→15%になったらIRRはどう変わるか、を定量化します。投資判断の堅牢性を確認し、どの変数が最もリスクに影響するかを特定するプロの必須スキルです。' },
  { id: 205, level: 3, category: 'IRR・DCF', question: '「モンテカルロシミュレーション」を不動産投資分析に応用する目的はどれですか？', choices: ['地震リスクを計算するため', '建築コストを見積もるため', '複数の不確実な変数を確率分布で設定し大量の試算でリターン分布を把握するため', '管理会社の評価をするため'], correct: 2, explanation: 'モンテカルロ法は家賃・空室率・金利・売却価格等を確率分布として設定し、数万回のシミュレーションでIRRやNPVの分布を算出します。「IRRが10%以上になる確率は75%」という形でリスクを定量化できます。' },
  { id: 206, level: 3, category: 'IRR・DCF', question: '不動産投資のDCFモデルで「レバードIRR」と「アンレバードIRR」の違いはどれですか？', choices: ['両者は同じ指標', 'アンレバードは税引き後・レバードは税引き前のIRR', 'レバードはプロ専用でアンレバードは初心者向け', 'レバードはローンを含む自己資金ベース、アンレバードはローンなしの物件単体のIRR'], correct: 3, explanation: 'アンレバードIRR = 借入なし前提の物件本体のリターン（物件の真の収益力）。レバードIRR = 借入込みで自己資金に対するリターン。好条件のレバレッジをかけるとレバードIRRはアンレバードを大きく上回ります。' },
  { id: 207, level: 3, category: 'IRR・DCF', question: '「Jカーブ効果」とは不動産ファンド投資でどのような現象を指しますか？', choices: ['投資初期に収益がマイナスになり、その後プラスに転じてJの字を描く収益カーブ', '物件価格がJ字型に上昇する現象', '入居率がJ字型に改善する現象', '金利がJ字型に低下する現象'], correct: 0, explanation: 'Jカーブは不動産ファンドの典型的な収益パターン。初期は取得費・リノベコスト・空室期間でマイナスになり、改善後に収益化、売却でプラスに転じます。LP投資家への説明に使われる概念です。' },
  { id: 208, level: 3, category: 'IRR・DCF', question: '「XIRR関数」（Excelの不規則なキャッシュフロー用IRR）を使う場面として正しいものはどれですか？', choices: ['毎月均等なキャッシュフローのみの場合', 'キャッシュフローの発生タイミングが不規則な場合（途中売却・追加投資等）', 'XIRR関数は不動産投資には使えない', '固定金利ローンの計算のみに使う'], correct: 1, explanation: 'IRR関数は期間が均等なCFを前提としますが、不動産では取得・売却・修繕タイミングが不規則。XIRR関数は日付と金額を対応させて正確なIRRを計算できます。プロの投資分析では必須のExcelスキルです。' },
  { id: 209, level: 3, category: '積算評価', question: '積算評価の計算式として正しいものはどれですか？', choices: ['年間家賃収入 × 利回り倍率', '固定資産税評価額 × 2倍', '土地評価額 + 建物評価額（再調達価格 × 残存年数/耐用年数）', '路線価 × 建ぺい率 × 容積率'], correct: 2, explanation: '積算評価 = 土地評価（路線価×補正率×地積）+ 建物評価（再調達価格×延床面積×残存年数/耐用年数）。銀行の担保評価として使われ、積算評価が高いほど融資が通りやすくなります。' },
  { id: 210, level: 3, category: '積算評価', question: '「再調達価格」とは何を指しますか？', choices: ['元々の建設コスト', '現在の市場売買価格', '固定資産税評価額', '現在同じ建物を建てるとしたら1㎡あたりいくらかかるかという単価'], correct: 3, explanation: '再調達価格は現時点での建設コスト。木造15万円/㎡、RC造20〜25万円/㎡が目安（地域・仕様により異なる）。これに延床面積×残存年数係数をかけて建物の積算価値を算出します。' },
  { id: 211, level: 3, category: '積算評価', question: '「積算評価 > 売買価格」の物件が投資家に好まれる理由はどれですか？', choices: ['物件が担保価値以下で購入でき、融資を受けやすく出口リスクが低いため', '積算評価が高いと利回りが自動的に上がるため', '積算評価が高いと固定資産税が下がるため', '銀行が必ず融資するため'], correct: 0, explanation: '積算評価超えで購入すると「担保余力がある」状態で銀行から有利な条件で融資を受けやすくなります。また収益性が低下しても担保評価内なら売却で借入完済できるため出口リスクが低い。' },
  { id: 212, level: 3, category: '積算評価', question: '路線価と公示地価の関係として正しいものはどれですか？', choices: ['路線価は公示地価の200%', '路線価は公示地価の約80%が目安で相続税・贈与税の計算に使う', '両者は全く同じ価格', '路線価は毎日更新される'], correct: 1, explanation: '公示地価は国土交通省が毎年1月1日時点で評価する正常価格。路線価（相続税路線価）は国税庁が設定し公示地価の約80%が目安。固定資産税評価額は公示地価の約70%が目安です。' },
  { id: 213, level: 3, category: '積算評価', question: '「借地権割合」が積算評価に影響する仕組みとして正しいものはどれですか？', choices: ['借地権があると積算評価が2倍になる', '借地権は積算評価に一切影響しない', '借地権付き建物は土地評価に借地権割合を乗じるため所有権より評価が低くなる', '借地権割合は全国一律70%'], correct: 2, explanation: '借地権割合（30〜90%：路線価図に記載）を土地評価額に乗じた額が借地権評価額。底地（地主の権利）と合計しても100%にはならない場合があります。借地権付き物件は担保評価が下がり融資が難しくなる場合があります。' },
  { id: 214, level: 3, category: '積算評価', question: '「収益評価と積算評価のかい離」が大きい物件への対処法として正しいものはどれですか？', choices: ['どちらの評価も同じなので問題ない', '積算評価が低い物件は常に売却すべき', '評価の差は融資に影響しない', '収益評価重視の金融機関を探すか自己資金を増やして対応する'], correct: 3, explanation: '地方高利回り物件は収益評価（DCF）では高いが積算評価が低く、都市部物件は逆になりがち。積算重視銀行では後者が有利。収益評価重視の信金・ノンバンク活用や高い自己資金投入で対応できます。' },
  { id: 215, level: 3, category: '積算評価', question: '「担保掛け目（LTV上限）」が融資に影響する仕組みとして正しいものはどれですか？', choices: ['銀行が積算評価に掛け目（例：70〜80%）をかけた額が融資上限の基準になる', '担保掛け目は売買価格に対して計算する', '担保掛け目は全金融機関で一律100%', '担保掛け目は築年数だけで決まる'], correct: 0, explanation: '融資上限 = 積算評価 × 掛け目（70〜90%）。例えば積算5,000万円・掛け目80%なら4,000万円が融資上限の目安。収益評価も加味する金融機関では収益還元評価 × 掛け目も計算されます。' },
  { id: 216, level: 3, category: '融資戦略', question: 'ポートフォリオ融資（複数物件一括融資）のメリットとして正しいものはどれですか？', choices: ['ポートフォリオ融資は金利が必ず高くなる', '管理が一本化でき追加物件取得時の審査が柔軟になる場合がある', '複数物件を持つほど毎物件の審査が厳しくなる', 'ポートフォリオ融資は個人には使えない'], correct: 1, explanation: 'ポートフォリオ融資は複数物件をまとめて評価・融資する手法。個別物件の弱点を全体のポートフォリオで補完でき、追加物件取得時の事務効率化、金利交渉力向上のメリットがあります。' },
  { id: 217, level: 3, category: '融資戦略', question: '「デット・ファイナンスとエクイティ・ファイナンスの最適ミックス」について正しいものはどれですか？', choices: ['デットとエクイティは全く同じコスト構造', 'エクイティは借入より必ずコストが低い', 'デット（借入）はコストが安いがリスクがあり、エクイティ（自己資本）は高コストだが柔軟性がある', 'デットを最大化するほど常に有利'], correct: 2, explanation: 'デット（ローン）は利息が経費計上でき税務メリットがありますが過剰レバレッジはリスク。エクイティ（自己資金）はコスト（機会費用）がありますが財務健全性を保ちます。最適比率は案件・市場環境・個人リスク許容度で異なります。' },
  { id: 218, level: 3, category: '融資戦略', question: '「クロスデフォルト条項」の意味として正しいものはどれですか？', choices: ['複数物件を同時に担保に入れることができる条項', 'デフォルト時に他の借入人が代わりに返済する条項', '金利が一定以上になると自動解除される条項', 'A物件のローンを滞納するとB物件のローンも期限の利益を失う可能性がある条項'], correct: 3, explanation: 'クロスデフォルト条項は複数のローン契約間で一つのデフォルトが他の全契約に波及する条項。複数銀行でローンを組む場合に含まれていることがあり、一物件の問題が全体に波及するリスクがあります。' },
  { id: 219, level: 3, category: '融資戦略', question: '「メザニンファイナンス」とは何ですか？', choices: ['シニアローンと自己資本の間に位置するリスク・リターンの中間的な資金調達手法', '最も安全な第一順位の担保ローン', '自己資金のみで行う投資手法', '政府系金融機関専用のローン'], correct: 0, explanation: 'メザニンは「中間の」という意味。第一順位担保ローン（シニアデット）より劣後し自己資本より優先する中間的な資金。高リターンを求める投資家が提供し、不動産開発や大型案件で活用されます。' },
  { id: 220, level: 3, category: '融資戦略', question: '「デット・サービス・カバレッジ・レシオ（DSCR）」1.25を融資条件とする場合、NOI600万円では最大年間返済額はいくらですか？', choices: ['600万円', '480万円', '750万円', '400万円'], correct: 1, explanation: 'DSCR = NOI ÷ 年間返済額 ≥ 1.25 なので、返済額 ≤ NOI ÷ 1.25 = 600 ÷ 1.25 = 480万円。月換算で40万円が上限。DSCRは不動産融資の中核指標でプロ投資家は必ず計算します。' },
  { id: 221, level: 3, category: '融資戦略', question: '「期限の利益喪失（EoD）」とはどのような状態ですか？', choices: ['融資審査が通過した状態', '元金返済が完了した状態', 'ローン返済の遅延・財務状況悪化等で銀行が一括返済を請求できる状態', '金利が優遇される状態'], correct: 2, explanation: '期限の利益喪失は元々分割返済できる「期限の利益」を失い、銀行が残債全額の即時返済を請求できる状態。発生条件：返済遅延・財務状況悪化・担保価値の著しい下落・虚偽申告等。最悪の事態です。' },
  { id: 222, level: 3, category: '融資戦略', question: '「事業性融資（投資ローン）」と「住宅ローン流用」の違いはどれですか？', choices: ['両方とも合法で金利だけが異なる', '住宅ローン流用の方が銀行に歓迎される', '事業性融資は個人には使えない', '事業性融資は用途を正直に申告する合法的な手法、住宅ローン流用は投資目的への不正使用で違法'], correct: 3, explanation: '住宅ローンを投資用物件に使うことは融資契約違反で発覚すれば一括返済を求められます。事業性融資（投資ローン）は用途を正確に申告した合法手法。コンプライアンスは長期的な信用に直結します。' },
  { id: 223, level: 3, category: '融資戦略', question: '銀行の「信用格付け」が投資家の融資条件に影響する仕組みとして正しいものはどれですか？', choices: ['格付けが高いほど低金利・高額融資が受けやすく、低いと条件が悪化する', '格付けは融資に一切影響しない', '格付けが低いほど銀行は積極的に融資する', '格付けは物件の評価のみに使われる'], correct: 0, explanation: '銀行は借入人の属性・財務・信用履歴を内部格付けで評価。高格付けほど金利優遇・融資上限拡大の恩恵があります。不動産投資家が「属性を育てる」ことが長期的に有利な融資条件につながります。' },
  { id: 224, level: 3, category: '税金・節税', question: '「不動産所得」と「事業所得」の区分はどのような基準で決まりますか？', choices: ['不動産収入があれば全て事業所得になる', '一定規模以上（5棟10室基準）を満たすと事業的規模となり事業所得的な特典が受けられる', '法人なら事業所得、個人なら不動産所得', 'アパートなら事業所得、マンションなら不動産所得'], correct: 1, explanation: '不動産所得の事業的規模は「5棟以上または10室以上」が目安（形式基準）。事業的規模だと青色申告65万円控除・事業専従者給与・貸倒損失の全額経費計上が可能になります。' },
  { id: 225, level: 3, category: '税金・節税', question: '「法人税実効税率」が個人の所得税を下回るのはどの所得水準からですか？', choices: ['所得が100万円を超えたら法人化が有利', '法人税は常に個人税より高い', '課税所得約900万円超が一般的な分岐点で、超えると法人化のメリットが出始める', '所得が5,000万円を超えないと法人化の意味がない'], correct: 2, explanation: '個人：課税所得900万超で税率33%+住民税10%=43%。法人税実効税率は約23〜30%。900万円超から差が生じ始めます。ただし法人維持コスト（税理士・社会保険等）を差し引いた実質差で判断が必要です。' },
  { id: 226, level: 3, category: '税金・節税', question: '「役員報酬」を活用した節税スキームの仕組みとして正しいものはどれですか？', choices: ['役員報酬は経費にならない', '役員報酬を増やすほど法人税が増える', '役員報酬は税務署に届け出ない', '法人から役員へ給与を支払い所得分散することで累進課税の適用税率を下げる'], correct: 3, explanation: '法人から役員（オーナー）に役員報酬を支払うことで①法人の課税所得が下がる②個人では給与所得控除が使える。家族を役員にして所得分散することで全体の税負担を最適化できます。' },
  { id: 227, level: 3, category: '税金・節税', question: '「建物の取得価格を土地と建物に合理的に分割」することが重要な理由はどれですか？', choices: ['建物のみが減価償却できるため、建物割合が高いほど年間の節税効果が大きくなるため', '土地も建物と同じく減価償却できるため', '分割方法は税金に影響しない', 'すべて土地として計上する方が節税になる'], correct: 0, explanation: '土地は非償却資産で減価償却不可。建物のみ償却可能。取得価格の建物割合が高いほど年間減価償却費が増え節税効果が高まります。固定資産税評価額・消費税額・不動産鑑定で合理的に按分します。' },
  { id: 228, level: 3, category: '税金・節税', question: '「相続税対策としての不動産投資」が有効とされる主な理由はどれですか？', choices: ['不動産は相続税が完全免除されるため', '不動産の相続税評価額（路線価・固定資産税評価額）が時価より低くなる場合があるため', '現金より不動産の方が常に相続税が高い', '不動産投資をすると相続税が自動的にゼロになる'], correct: 1, explanation: '現金1億円を不動産に換えると相続税評価額が下がる場合があります。土地は路線価（時価の約80%）、建物は固定資産税評価額（時価の約60〜70%）で評価されるためです。ただしタワマン節税規制等の改正に注意が必要です。' },
  { id: 229, level: 3, category: '税金・節税', question: '「消費税の課税事業者」になることで不動産投資に影響することはどれですか？', choices: ['住宅賃料にも消費税がかかる', '消費税は不動産投資に一切関係ない', '建物売却時に消費税が発生し、事業用賃料（事務所・倉庫等）は消費税課税対象になる', '課税事業者になると固定資産税が免除される'], correct: 2, explanation: '住宅賃貸は消費税非課税ですが、事務所・倉庫・駐車場（建物付属）賃料は課税対象。また建物売却は消費税課税。課税売上5,000万円超で課税事業者となり、インボイス制度への対応も必要になります。' },
  { id: 230, level: 3, category: '税金・節税', question: '「青色事業専従者給与」の活用が節税になる仕組みとして正しいものはどれですか？', choices: ['青色専従者給与は全員に支払える', '専従者給与は100万円まで無条件で経費になる', '専従者給与を払うと扶養控除が増える', '配偶者等に実際の業務対価として給与を支払い経費化することで所得分散・節税ができる'], correct: 3, explanation: '事業的規模の不動産所得がある場合、配偶者等家族への青色事業専従者給与が経費認定されます。ただし「専従」要件（6ヶ月超業務従事）と「相当の給与額」が必要。税務調査での否認リスクに注意が必要です。' },
  { id: 231, level: 3, category: '税金・節税', question: '「所得税・住民税の総合課税」と「分離課税」の違いとして正しいものはどれですか？', choices: ['不動産の賃貸収入は総合課税（累進）、譲渡所得は分離課税（一定税率）で計算する', '不動産収入は全て分離課税', '総合課税と分離課税は同じ税率', '給与所得者には分離課税が適用されない'], correct: 0, explanation: '賃貸収入（不動産所得）は他の所得と合算する総合課税で累進税率（最高45%）適用。売却益（譲渡所得）は分離課税で短期39%・長期20%。この違いが投資戦略（保有vs売却）の判断に大きく影響します。' },
  { id: 232, level: 3, category: '税金・節税', question: '「繰越欠損金」を法人不動産投資で活用する方法として正しいものはどれですか？', choices: ['繰越欠損金は法人では使えない', '法人の赤字（欠損金）を最大10年間繰り越して将来の黒字と相殺し法人税を圧縮できる', '欠損金は翌年のみ使える', '繰越欠損金を使うと法人税が増える'], correct: 1, explanation: '法人は欠損金を最大10年（中小企業等）繰り越せます。初年度に大きな減価償却費で赤字にし、将来の黒字と相殺して法人税を平準化できます。個人でも損益通算・繰越控除（3年）の活用が可能です。' },
  { id: 233, level: 3, category: '法人化', question: '不動産投資法人の設立形態として「合同会社（LLC）」が選ばれる理由はどれですか？', choices: ['合同会社の方が銀行融資を受けやすいため', '合同会社は不動産投資に使えない', '設立費用が株式会社より安く（6万円程度）、決算公告義務がなく運営コストが低いため', '株式会社より信頼性が高いため'], correct: 2, explanation: '合同会社は設立費用6万円（株式会社は20〜25万円）、決算公告不要、役員任期なしで維持コストが低い。ただし社会的認知度が株式会社より低く、一部の取引先・金融機関で不利になるケースもあります。' },
  { id: 234, level: 3, category: '法人化', question: '個人から法人への不動産売却（法人化）で発生するコストとして正しいものはどれですか？', choices: ['法人化すると全てのコストが免除される', '登録免許税だけが発生する', '法人化のコストは一律10万円', '不動産取得税・登録免許税・個人の譲渡所得税が発生し相当のコストがかかる'], correct: 3, explanation: '個人から法人への不動産移転には①個人に譲渡所得税（短期39%/長期20%）②法人側に不動産取得税（3〜4%）③登録免許税（2%）が発生。これらのコストと節税メリットを比較したシミュレーションが必須です。' },
  { id: 235, level: 3, category: '法人化', question: '「資産管理法人」を設立する主な目的として正しいものはどれですか？', choices: ['不動産収入の法人化による節税・相続対策・法人名義での融資活用のため', '資産管理法人は節税に使えない', '法人を作ると固定資産税が2倍になる', '資産管理法人は大企業専用の仕組み'], correct: 0, explanation: '資産管理法人の目的：①累進税率回避（役員報酬で所得分散）②法人税実効税率活用③法人への資産移転による相続税対策④将来の事業継承⑤法人名義融資による属性活用。プロ投資家の定番手法です。' },
  { id: 236, level: 3, category: '法人化', question: '「法人の決算期」を変更する節税上の意味として正しいものはどれですか？', choices: ['決算期は一度決めたら変更できない', '消費税課税事業者判定や事業年度をコントロールして課税タイミングを最適化できる', '決算期は税金に影響しない', '決算期を3月にしないといけない'], correct: 1, explanation: '法人は定款変更で決算期を自由に設定できます。消費税の課税事業者判定は前々事業年度の売上が基準のため、事業年度設定で免税期間を延ばす効果があります。設立直後は特に活用できる手法です。' },
  { id: 237, level: 3, category: '法人化', question: '法人で不動産を取得する場合でも「小規模企業共済」はどのように活用できますか？', choices: ['法人は小規模企業共済を使えない', '小規模企業共済は廃止された', '法人自体は加入できないが法人の役員個人として加入し節税できる', '法人の方が優遇されるため個人より有利'], correct: 2, explanation: '小規模企業共済は個人事業主・法人役員が加入できる退職金積立制度。掛金は全額所得控除になる節税効果があります。法人自体は加入できませんが、法人を経営するオーナー社長個人として活用できます。' },
  { id: 238, level: 3, category: '法人化', question: '「家族信託 + 法人化」の組み合わせが相続対策で有効な理由はどれですか？', choices: ['家族信託と法人化を組み合わせると税金がゼロになる', 'この組み合わせはリスクが高く推奨されない', '家族信託は法人に使えない', '認知症リスクに備えながら法人株式を通じた円滑な資産承継ができるため'], correct: 3, explanation: '家族信託でオーナーが認知症になっても受託者が不動産管理継続できる仕組みを作り、同時に法人化で自社株（不動産保有法人の株式）を生前から後継者に移転することで、スムーズな事業承継と相続対策を両立できます。' },
  { id: 239, level: 3, category: '法人化', question: '「持株会社（ホールディングス）」構造を不動産投資で使う目的として正しいものはどれですか？', choices: ['グループ全体の税務最適化・資金移動の柔軟性・各物件法人の倒産隔離のため', '持株会社は税金が2倍になる', '持株会社は大企業専用', '持株会社を作ると融資が受けられなくなる'], correct: 0, explanation: 'ホールディングス構造では持株会社が各物件保有子会社の株式を保有。子会社間の資金移動最適化・連結納税・各法人の倒産隔離・段階的な事業承継が可能になります。資産5億円超の大規模投資家が活用します。' },
  { id: 240, level: 3, category: '法人化', question: '法人から個人への「不動産の無償贈与」に対して税務上発生するリスクはどれですか？', choices: ['法人から個人への無償移転は非課税', '時価での売買とみなされ法人には法人税、個人には贈与税が課税される', '贈与税のみが発生する', '法人税のみが発生する'], correct: 1, explanation: '法人から個人への無償or低廉譲渡は「時価で売買したとみなす」。法人側：時価と実際売価の差が益金算入（法人税）。個人側：時価と代金の差額が一時所得または贈与税の対象になります。' },
  { id: 241, level: 3, category: 'レバレッジ', question: '「負のレバレッジ」が発生する条件として正しいものはどれですか？', choices: ['LTVが50%以下の場合', '自己資金が多すぎる場合', '物件の総収益率（FCR）がローン定数（K%）を下回った場合', '金利が固定の場合'], correct: 2, explanation: 'レバレッジ効果の符号はFCRとK%の大小で決まります。FCR > K%: 正のレバレッジ（借りるほど自己資金利回りが上がる）。FCR < K%: 負のレバレッジ（借りるほど自己資金利回りが下がる）。この関係を理解することはプロ投資家の必須知識です。' },
  { id: 242, level: 3, category: 'レバレッジ', question: '「財務レバレッジ比率」が高いポートフォリオのリスクとして正しいものはどれですか？', choices: ['財務レバレッジが高いほど常に安全', 'レバレッジ比率はリスクと無関係', '借入を増やすと金利が必ず下がる', '金利上昇・空室増加・景気悪化時に債務不履行リスクが急上昇する'], correct: 3, explanation: '高レバレッジは好況時に大きなリターンをもたらしますが、逆境時の脆弱性も高めます。家賃収入の10〜15%低下でCFがマイナスになるような過剰レバレッジは破綻リスクと隣り合わせです。' },
  { id: 243, level: 3, category: 'レバレッジ', question: '「レバレッジの限界（最適LTV）」を考える際の基準として正しいものはどれですか？', choices: ['FCR > K%が維持でき、ストレス時（金利+2%・空室+10%）でもDSCRが1.0以上保てる水準', 'LTV100%を目指すべき', '自己資金ゼロが最も効率的', 'LTVは常に固定で考える必要はない'], correct: 0, explanation: '最適LTVは正のレバレッジが維持でき、かつストレス時でも返済継続できる水準。一般的に70〜80%LTVが安全域とされますが、物件・エリア・投資家の財務力によって異なります。' },
  { id: 244, level: 3, category: 'レバレッジ', question: '「ローン定数（K%）」の計算式として正しいものはどれですか？', choices: ['借入残高 ÷ 年間返済額 × 100', '年間返済額 ÷ 借入残高 × 100', '金利 × 期間', 'NOI ÷ 物件価格 × 100'], correct: 1, explanation: 'ローン定数K% = 年間返済額 ÷ 借入残高 × 100。金利2.5%・30年の場合K%≈4.7%。FCRがK%を上回れば正のレバレッジ。K%は金利だけでなく返済期間にも影響されます。' },
  { id: 245, level: 3, category: 'レバレッジ', question: '「エクイティ・マルチプル（EM）」とは何ですか？', choices: ['物件の積算評価倍率', '家賃の年間倍率', '投資期間中の総回収額 ÷ 初期投資額（自己資金）で何倍になったかを示す指標', '建物の耐用年数倍率'], correct: 2, explanation: 'EM = 総回収額（CF累計 + 売却収入）÷ 自己資金投入額。EM2.0なら「自己資金が2倍になって回収された」意味。IRRは時間を考慮しますがEMは「何倍になったか」をシンプルに示します。両指標を併用するのがプロの手法です。' },
  { id: 246, level: 3, category: '再建築不可・相続', question: '再建築不可物件の「43条但し書き申請」とはどのような制度ですか？', choices: ['全ての再建築不可物件を自動的に解除する制度', '申請すれば必ず建て替えできる制度', '43条申請は廃止された', '接道要件を満たさない土地でも建築審査会の同意を得ることで建築が認められる場合がある制度'], correct: 3, explanation: '建築基準法43条但し書きは、接道義務を満たさない土地でも建築審査会の同意で建築許可が下りる場合がある制度。通路が現況通路として公衆に使われている等の条件が必要。再建築不可物件の「出口」を拓く重要手段です。' },
  { id: 247, level: 3, category: '再建築不可・相続', question: '相続した収益不動産を「物納」する際の注意点として正しいものはどれですか？', choices: ['物納できる財産には優先順位があり、担保権が設定された不動産等は物納不適格になる場合がある', '相続不動産は常に物納できる', '物納すると相続税が増える', '物納は現金がない場合に使える制度で条件は一切ない'], correct: 0, explanation: '相続税の物納は延納でも支払いが困難な場合に認められます。ただし①担保権が設定されている②係争中③共有持分等は物納不適格。収益不動産を物納すると賃料収入がなくなるデメリットも考慮が必要です。' },
  { id: 248, level: 3, category: '再建築不可・相続', question: '「配偶者居住権」が新設（2020年）された不動産投資への影響として正しいものはどれですか？', choices: ['配偶者居住権は収益不動産には無関係', '配偶者が自宅に住み続ける権利と財産権が分離でき、相続財産の分割に影響する', '配偶者居住権があると固定資産税が免除される', '配偶者居住権は相続税を増加させる'], correct: 1, explanation: '配偶者居住権は配偶者が自宅を使用する権利（居住権）と所有権を分離できる制度。居住権は相続財産の一部として評価されるため、収益不動産を含む相続全体の財産分割計画に影響します。' },
  { id: 249, level: 3, category: '再建築不可・相続', question: '「二次相続」を考慮した不動産の相続対策として正しいものはどれですか？', choices: ['配偶者控除を最大限使うことが常に有利', '二次相続対策は不要', '一次相続（配偶者死亡時）の配偶者控除を使いすぎると二次相続（子供）で税負担が増える場合がある', '配偶者に全財産を相続させれば税金はゼロ'], correct: 2, explanation: '一次相続で配偶者控除（1億6,000万円まで無税）を最大化すると配偶者の財産が増え、二次相続時に大きな税負担になる場合があります。一次・二次の合計税額をシミュレーションして最適な分割を設計する必要があります。' },
  { id: 250, level: 3, category: '再建築不可・相続', question: '「遺留分侵害額請求」が不動産相続で問題になる場面として正しいものはどれですか？', choices: ['遺留分は不動産には適用されない', '遺言書があれば遺留分は完全に排除できる', '遺留分侵害は民事ではなく刑事事件', '特定の相続人に不動産を集中させた場合に他の相続人から金銭請求される可能性がある'], correct: 3, explanation: '遺留分は一定の相続人（子・配偶者・直系尊属）に保障された最低限の相続分。収益不動産を特定の子に集中させた場合、他の子から遺留分侵害額請求（金銭）が来る可能性があります。事前の対策として生命保険・生前贈与・遺言の組み合わせが有効です。' },
];
